/// Events a pane emits upward to the workspace. A pane never mutates sibling
/// panes or the workspace's pane list directly; it asks its owner instead.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PaneEvent {
    /// The pane was interacted with and should become the active pane.
    FocusRequested,
    SetNotificationFilter {
        tone: Option<ToastTone>,
    },
    ClearNotifications,
    /// This pane owns the currently visible drop ghost. The workspace tracks
    /// one owner so pointer-leave cleanup stays O(1) with many splits.
    DragPreviewActivated,
    /// The pointer entered a tab strip; tab insertion must supersede every
    /// structural pane target.
    TabBarDragEntered,
    /// Run a workspace-owned command from pane-local tab-strip chrome.
    CommandRequested(CommandId),
    /// Create a sibling beside this pane in the requested direction.
    SplitRequested(SplitDirection),
    /// Toggle this pane as the sole visible pane in the workspace pane region.
    ToggleMaximizedRequested,
    /// The pane should be removed (its close control was used, or it emptied).
    CloseRequested,
    /// A tab-local close control was used; the workspace owns dirty handling.
    CloseItemRequested {
        item_id: u64,
    },
    /// A tab-local dirty prompt chose to discard the item.
    DiscardItemRequested {
        item_id: u64,
    },
    /// A configuration tab's dirty prompt requested a save.
    SaveItemRequested {
        item_id: u64,
    },
    RenameItemRequested {
        item_id: u64,
        name: String,
    },
    SaveRunConfigurationRequested {
        item_id: u64,
    },
    DeleteRunConfigurationRequested {
        item_id: u64,
    },
    RunConfigurationRequested {
        item_id: u64,
    },
    /// A tab was dropped onto this pane or one of its split targets.
    MoveItemRequested {
        item_id: u64,
        target: PaneDropTarget,
    },
    /// Active editor state changed. Cursor-only changes do not dirty the tab.
    EditorStateChanged {
        item_id: u64,
        dirty: Option<bool>,
    },
    RoomUpdateRequested {
        item_id: u64,
        update: Vec<u8>,
    },
    /// An editor requested the workspace-level command palette.
    OpenCommandPaletteRequested,
    /// A query item asked to run SQL; the workspace dispatches it to execution.
    ExecuteRequested {
        item_id: u64,
        sql: String,
    },
    /// A database-backed snapshot requested a live refresh. Workspace owns
    /// connection selection and may reconnect before executing.
    RefreshDatabaseItemRequested {
        item_id: u64,
    },
    OpenDatabaseDdlRequested {
        item_id: u64,
    },
    /// The retained row window is full and the user asked to continue past it.
    LoadNextRowWindowRequested {
        item_id: u64,
    },
    OpenDataResultsRequested {
        item_id: u64,
    },
    ExportResultRequested {
        item_id: u64,
        sql: String,
        format: sift_protocol::ExportFormat,
    },
    CancelResultExportRequested {
        item_id: u64,
    },
    ApplyResultTransformRequested {
        item_id: u64,
        sql: String,
        transform: sift_protocol::ResultTransform,
    },
    EditResultCellRequested {
        item_id: u64,
    },
    PasteResultCellRequested {
        item_id: u64,
        text: String,
    },
    RevertResultCellRequested {
        item_id: u64,
    },
    DeleteResultRowRequested {
        item_id: u64,
    },
    ReviewStagedResultEditsRequested {
        item_id: u64,
    },
    SubmitResultCellEditRequested {
        item_id: u64,
        text: String,
    },
    SubmitJsonResultEditRequested {
        item_id: u64,
        text: String,
        preview: bool,
    },
    CancelResultCellEditRequested {
        item_id: u64,
    },
    ResultSelectionChanged,
    OpenResultRowJsonRequested {
        item_id: u64,
    },
    ReviewOutcomeUnknownRequested {
        item_id: u64,
        sql: String,
    },
    CapturePlanRequested {
        item_id: u64,
        sql: String,
    },
    OpenPlanCapturesRequested {
        item_id: u64,
        sql: String,
    },
    ExplainRequested {
        item_id: u64,
        sql: String,
        analyze: bool,
    },
    HistoryRequested {
        item_id: u64,
        cursor: Option<String>,
    },
    RerunHistoryRequested {
        item_id: u64,
        sql: String,
    },
    /// An editor wants semantic work done for one of its revisions. The
    /// workspace owns the connection and the debounce policy.
    SemanticRequested {
        item_id: u64,
        revision: u64,
        request: SemanticRequestKind,
    },
}

