    /// Headless renderer benchmark hook. Product code receives the same state
    /// through `ExecutorEvent::RepositoryStatusLoaded`.
    #[cfg(feature = "benchmark")]
    #[doc(hidden)]
    pub fn apply_repository_status_benchmark(
        &mut self,
        status: sift_protocol::VcsStatus,
        cold: bool,
        cx: &mut Context<Self>,
    ) {
        if cold {
            self.repository.select_workspace(None);
        }
        self.selected_workspace_id = Some(1);
        self.repository.select_workspace(Some(1));
        let (_, request_id) = self
            .repository
            .begin_refresh()
            .expect("benchmark workspace must be selected");
        let _ = self
            .repository
            .apply_status_result(1, request_id, Ok(Some(status)));
        self.left_dock.presentation.open = true;
        self.active_left_panel = LeftPanel::Git;
        cx.notify();
    }

    fn current_repository_presentation(&self, cx: &App) -> RepositoryWorkspacePresentation {
        let selected_diff = self.panes.get(self.active_pane).and_then(|pane| {
            let pane = pane.read(cx);
            let item_id = pane.active_item()?.id;
            self.repository_diff_items.get(&item_id)
        });
        RepositoryWorkspacePresentation {
            panel_size: self.left_dock.presentation.size,
            selected_path: self.repository.selected_path().map(|path| path.0.clone()),
            selected_diff_path: selected_diff.map(|state| state.path.0.clone()),
            selected_diff_side: selected_diff.map(|state| state.side),
            grouping: self.settings.repository.grouping,
            sort: self.settings.repository.sort,
            view: self.settings.repository.view,
            primary_action: self.settings.repository.primary_action,
        }
    }

    pub fn snapshot(&self, cx: &App) -> PresentationState {
        let mut instance_workspaces = self.workspace_presentations.clone();
        instance_workspaces.extend(
            self.workspace_sessions
                .iter()
                .map(|(instance_id, session)| {
                    (
                        instance_id.clone(),
                        session.snapshot(instance_id.clone(), cx),
                    )
                }),
        );
        let mut repository_workspaces = self.repository_workspaces.clone();
        if let Some(workspace_id) = self.selected_workspace_id {
            repository_workspaces.insert(workspace_id, self.current_repository_presentation(cx));
        }
        PresentationState {
            dark_theme: self.dark_theme,
            window: self.window_presentation.clone(),
            workspace: WorkspacePresentation {
                left_dock: self.left_dock.presentation.clone(),
                right_dock: self.right_dock.presentation.clone(),
                bottom_dock: self.bottom_dock.presentation.clone(),
                left_panel: self.active_left_panel,
                bottom_tool: self.active_bottom_tool,
                panes: self
                    .panes
                    .iter()
                    .map(|pane| pane.read(cx).snapshot())
                    .collect(),
                pane_layout: Some(self.pane_layout.clone()),
                pane_flexes: Vec::new(),
                active_pane: self.active_pane,
                workspace_id: self.selected_workspace_id,
                instance_id: self.selected_instance_id.clone(),
            },
            instance_workspaces,
            repository_commit_drafts: self.repository_commit_drafts.clone(),
            repository_workspaces,
            palette_recents: self.palette_recents.clone(),
            ..PresentationState::default()
        }
    }

    fn persist(&mut self, cx: &mut Context<Self>) {
        if self.store.is_none() || self.presentation_persist_pending {
            return;
        }
        self.presentation_persist_pending = true;
        cx.spawn(async move |shell, cx| {
            cx.background_executor()
                .timer(PRESENTATION_PERSIST_DEBOUNCE)
                .await;
            let _ = shell.update(cx, |shell, cx| {
                shell.presentation_persist_pending = false;
                let Some(store) = shell.store.clone() else {
                    return;
                };
                let state = shell.snapshot(cx);
                cx.background_spawn(async move {
                    let _ = store.save(&state);
                })
                .detach();
            });
        })
        .detach();
    }

    fn persist_now(&self, cx: &mut Context<Self>) {
        let Some(store) = self.store.clone() else {
            return;
        };
        let state = self.snapshot(cx);
        cx.background_spawn(async move {
            let _ = store.save(&state);
        })
        .detach();
    }

    fn fit_side_docks_to_width(&mut self, width: f32) {
        let sizes = dock_layout::fit_side_docks(
            width,
            self.left_dock.presentation.size,
            self.right_dock.presentation.size,
            self.left_dock.presentation.open,
            self.right_dock.presentation.open,
        );
        self.left_dock.presentation.size = sizes.left;
        self.right_dock.presentation.size = sizes.right;
    }

    fn fit_docks_to_viewport(&mut self, width: f32, height: f32) {
        self.fit_side_docks_to_width(width);

        let vertical_chrome: f32 =
            (ThemeMetrics::default().toolbar_height + ThemeMetrics::default().status_height).into();
        self.bottom_dock.presentation.size = dock_layout::fit_bottom_dock(
            (height - vertical_chrome).max(0.0),
            self.bottom_dock.presentation.size,
        );
    }

    fn resize_dock(
        &mut self,
        event: &gpui::DragMoveEvent<DockResizeDrag>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let dock = event.drag(cx).dock;
        let width: f32 = event.bounds.size.width.into();
        let height: f32 = event.bounds.size.height.into();
        let pointer_x: f32 = (event.event.position.x - event.bounds.left()).into();
        let pointer_y: f32 = (event.event.position.y - event.bounds.top()).into();
        let previous_sizes = (
            self.left_dock.presentation.size,
            self.right_dock.presentation.size,
            self.bottom_dock.presentation.size,
        );

        match dock {
            DockId::Left | DockId::Inspector => {
                let requested = match dock {
                    DockId::Left => pointer_x,
                    DockId::Inspector => width - pointer_x,
                    DockId::Bottom => unreachable!(),
                };
                let sizes = dock_layout::resize_side_dock(
                    width,
                    dock_layout::SideDockSizes {
                        left: self.left_dock.presentation.size,
                        right: self.right_dock.presentation.size,
                    },
                    self.left_dock.presentation.open,
                    self.right_dock.presentation.open,
                    dock,
                    requested,
                );
                self.left_dock.presentation.size = sizes.left.round();
                self.right_dock.presentation.size = sizes.right.round();
            }
            DockId::Bottom => {
                self.bottom_dock.presentation.size =
                    dock_layout::fit_bottom_dock(height, height - pointer_y).round();
            }
        }
        let current_sizes = (
            self.left_dock.presentation.size,
            self.right_dock.presentation.size,
            self.bottom_dock.presentation.size,
        );
        if current_sizes != previous_sizes {
            self.queue_workspace_resize(window, cx);
        }
    }

    fn finish_dock_resize(&mut self, _: &DockResizeDrag, _: &mut Window, cx: &mut Context<Self>) {
        self.persist(cx);
    }

    fn resize_panes(
        &mut self,
        event: &gpui::DragMoveEvent<PaneResizeDrag>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let drag = event.drag(cx);
        let (pointer, available, minimum) = match drag.axis {
            PaneAxis::Horizontal => (
                f32::from(event.event.position.x - event.bounds.left()).round(),
                f32::from(event.bounds.size.width),
                PANE_MIN_WIDTH,
            ),
            PaneAxis::Vertical => (
                f32::from(event.event.position.y - event.bounds.top()).round(),
                f32::from(event.bounds.size.height),
                PANE_MIN_HEIGHT,
            ),
        };
        let previous = self.pane_layout.clone();
        pane_layout::resize(
            &mut self.pane_layout,
            &drag.path,
            drag.boundary,
            pointer,
            available,
            minimum,
        );
        if self.pane_layout != previous {
            self.queue_workspace_resize(window, cx);
        }
    }

    fn queue_workspace_resize(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.workspace_resize_frame_pending {
            return;
        }
        self.workspace_resize_frame_pending = true;
        cx.notify();
        cx.on_next_frame(window, |shell, _, _| {
            shell.workspace_resize_frame_pending = false;
        });
    }

    fn finish_pane_resize(&mut self, _: &PaneResizeDrag, _: &mut Window, cx: &mut Context<Self>) {
        self.persist(cx);
    }

    fn capture_window_bounds(&mut self, window_bounds: WindowBounds) {
        let maximized = matches!(window_bounds, WindowBounds::Maximized(_));
        let bounds = window_bounds.get_bounds();
        self.window_presentation.bounds = crate::presentation::Rect {
            x: bounds.origin.x.into(),
            y: bounds.origin.y.into(),
            width: bounds.size.width.into(),
            height: bounds.size.height.into(),
        };
        self.window_presentation.maximized = maximized;
    }

    fn split_pane(&mut self, _: &SplitPane, window: &mut Window, cx: &mut Context<Self>) {
        self.split_pane_in_direction(SplitDirection::Right, window, cx);
    }

    fn split_pane_in_direction(
        &mut self,
        direction: SplitDirection,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let id = self.next_id;
        self.next_id += 1;
        let target_id = self.panes[self.active_pane].read(cx).id;
        let source_has_items = self
            .panes
            .get(self.active_pane)
            .is_some_and(|pane| !pane.read(cx).items.is_empty());
        let pane = cx.new(|cx| {
            Pane::from_presentation(
                PanePresentation {
                    id,
                    items: source_has_items
                        .then(|| ItemPresentation {
                            id,
                            kind: ItemKind::Welcome,
                            title: "New pane".into(),
                            dirty: false,
                            source: None,
                            last_result: None,
                        })
                        .into_iter()
                        .collect(),
                    active_item: 0,
                },
                self.vim_mode_default(),
                cx,
            )
        });
        cx.subscribe_in(&pane, window, Self::on_pane_event).detach();
        self.panes.push(pane);
        pane_layout::split(&mut self.pane_layout, target_id, id, direction);
        self.maximized_pane_id = None;
        self.sync_pane_layout_view(cx);
        self.active_pane = self.panes.len() - 1;
        self.focus_active_pane(window, cx);
        self.persist(cx);
        cx.notify();
    }

    /// Move keyboard focus to the active pane's editor (or the pane itself).
    /// Called whenever the active pane changes or a modal is dismissed so focus
    /// is never orphaned — an orphaned focus silently drops all keybindings.
    fn focus_active_pane(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.focused_surface = WorkspaceSurface::Editor;
        self.connection_nav_g_pending = false;
        self.pane_input = false;
        if let Some(pane) = self.panes.get(self.active_pane) {
            pane.read(cx).active_focus_handle(cx).focus(window, cx);
        }
    }

    fn focus_connections(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.active_left_panel = LeftPanel::Connections;
        self.left_dock.presentation.open = true;
        self.fit_side_docks_to_width(window.window_bounds().get_bounds().size.width.into());
        self.focused_surface = WorkspaceSurface::Connections;
        self.normalize_connection_selection();
        self.connections_focus_handle.focus(window, cx);
        self.persist(cx);
        cx.notify();
    }

    fn focus_active_left_panel_surface(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let (surface, focus_handle) = match self.active_left_panel {
            LeftPanel::Connections => (
                WorkspaceSurface::Connections,
                self.connections_focus_handle.clone(),
            ),
            LeftPanel::Collaboration => (
                WorkspaceSurface::Collaboration,
                self.collaboration_focus_handle.clone(),
            ),
            LeftPanel::Git => (WorkspaceSurface::Git, self.repository_focus_handle.clone()),
            LeftPanel::SavedQueries => (
                WorkspaceSurface::SavedQueries,
                self.saved_queries_focus_handle.clone(),
            ),
            LeftPanel::QueryHistory => (
                WorkspaceSurface::QueryHistory,
                self.query_history_focus_handle.clone(),
            ),
            LeftPanel::QueryOutline => (
                WorkspaceSurface::QueryOutline,
                self.query_outline_focus_handle.clone(),
            ),
        };
        self.focused_surface = surface;
        focus_handle.focus(window, cx);
        cx.notify();
    }

    fn open_connections_find(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.connections_find_open = true;
        self.invalidate_connection_projection();
        self.connection_nav_selected = 0;
        self.connections_scroll_handle
            .scroll_to_item(0, ScrollStrategy::Top);
        self.connections_find_input
            .focus_handle(cx)
            .focus(window, cx);
        cx.notify();
    }

    fn close_connections_find(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.connections_find_open = false;
        self.connections_find_query.clear();
        self.connections_find_input
            .update(cx, |input, cx| input.set_text("", cx));
        self.invalidate_connection_projection();
        self.normalize_connection_selection();
        self.connections_focus_handle.focus(window, cx);
        cx.notify();
    }

    fn open_repository_filter(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.repository_filter_open = true;
        self.repository_filter_input
            .read(cx)
            .focus_handle(cx)
            .focus(window, cx);
        cx.notify();
    }

    fn close_repository_filter(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.repository_filter_open = false;
        self.repository_filter_input
            .update(cx, |input, cx| input.set_text("", cx));
        self.repository.set_filter("");
        self.repository_focus_handle.focus(window, cx);
        cx.notify();
    }

    fn focus_inspector(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.right_dock.presentation.open = true;
        self.fit_side_docks_to_width(window.window_bounds().get_bounds().size.width.into());
        self.focused_surface = WorkspaceSurface::Inspector;
        self.inspector_focus_handle.focus(window, cx);
        self.persist(cx);
        cx.notify();
    }

    fn select_result_inspector_view(
        &mut self,
        view: ResultInspectorView,
        cx: &mut Context<Self>,
    ) -> bool {
        let Some((item_id, _)) = self.focused_pane_results_item(cx) else {
            return false;
        };
        if view == ResultInspectorView::RelationDefinition
            && self.focused_database_item(cx).map(|(id, _)| id) != Some(item_id)
        {
            return false;
        }
        self.result_inspector_views.insert(item_id, view);
        self.inspector_g_pending = false;
        cx.notify();
        true
    }

    fn move_result_inspector_view(&mut self, delta: isize, cx: &mut Context<Self>) -> bool {
        let Some((item_id, _)) = self.focused_pane_results_item(cx) else {
            return false;
        };
        let mut views = vec![
            ResultInspectorView::Value,
            ResultInspectorView::Fields,
            ResultInspectorView::RowJson,
        ];
        if self.focused_database_item(cx).map(|(id, _)| id) == Some(item_id) {
            views.push(ResultInspectorView::RelationDefinition);
        }
        let current = self
            .result_inspector_views
            .get(&item_id)
            .copied()
            .unwrap_or_default();
        let index = views
            .iter()
            .position(|view| *view == current)
            .unwrap_or_default()
            .saturating_add_signed(delta)
            .min(views.len() - 1);
        self.select_result_inspector_view(views[index], cx)
    }

    fn move_inspector_field_selection(&mut self, delta: isize, cx: &mut Context<Self>) -> bool {
        let Some((_, results)) = self.focused_pane_results_item(cx) else {
            return false;
        };
        let field_count = results.read(cx).inspector_fields().len();
        if field_count == 0 {
            return false;
        }
        self.inspector_field_selected = self
            .inspector_field_selected
            .saturating_add_signed(delta)
            .min(field_count - 1);
        self.inspector_g_pending = false;
        cx.notify();
        true
    }

    fn toggle_selected_inspector_field(&mut self, cx: &mut Context<Self>) -> bool {
        let Some((_, results)) = self.focused_pane_results_item(cx) else {
            return false;
        };
        let Some(field) = results
            .read(cx)
            .inspector_fields()
            .get(self.inspector_field_selected)
            .cloned()
        else {
            return false;
        };
        results.update(cx, |results, cx| {
            results.set_column_included(field.source_column, !field.included, cx)
        });
        true
    }

    fn set_all_inspector_fields(&mut self, included: bool, cx: &mut Context<Self>) -> bool {
        let Some((_, results)) = self.focused_pane_results_item(cx) else {
            return false;
        };
        results.update(cx, |results, cx| {
            results.set_all_columns_included(included, cx)
        });
        true
    }

    fn toggle_inspector_row_json_fold(&mut self, cx: &mut Context<Self>) -> bool {
        let Some((_, results)) = self.focused_pane_results_item(cx) else {
            return false;
        };
        results.update(cx, |results, cx| results.toggle_row_json_folded(cx));
        true
    }

    fn toggle_inspector_row_json_wrap(&mut self, cx: &mut Context<Self>) -> bool {
        let Some((_, results)) = self.focused_pane_results_item(cx) else {
            return false;
        };
        results.update(cx, |results, cx| results.toggle_row_json_wrapped(cx));
        true
    }

    fn focus_inspector_row_json_filter(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> bool {
        let Some((_, results)) = self.focused_pane_results_item(cx) else {
            return false;
        };
        results
            .read(cx)
            .row_json_filter_input()
            .focus_handle(cx)
            .focus(window, cx);
        true
    }

    fn copy_inspector_selection(&mut self, cx: &mut Context<Self>) -> bool {
        let Some((item_id, results)) = self.focused_pane_results_item(cx) else {
            return false;
        };
        let view = self
            .result_inspector_views
            .get(&item_id)
            .copied()
            .unwrap_or_default();
        let text = match view {
            ResultInspectorView::Fields | ResultInspectorView::RelationDefinition => return false,
            ResultInspectorView::Value => results
                .read(cx)
                .selected_value()
                .map(|selected| render_value(&selected.value).text),
            ResultInspectorView::RowJson => results
                .read(cx)
                .selected_row_json()
                .and_then(|selected| serde_json::to_string_pretty(&selected.value).ok()),
        };
        let Some(text) = text else {
            return false;
        };
        cx.write_to_clipboard(gpui::ClipboardItem::new_string(text));
        true
    }

    fn show_result_row_json(&mut self, item_id: u64, window: &mut Window, cx: &mut Context<Self>) {
        let selected_row = self.panes.iter().find_map(|pane| {
            pane.read(cx)
                .results
                .get(&item_id)
                .map(|results| results.read(cx).selected_row_json().is_some())
        });
        if selected_row != Some(true) {
            self.show_toast("Select a result row to inspect it as JSON".into(), cx);
            return;
        }
        self.result_inspector_views
            .insert(item_id, ResultInspectorView::RowJson);
        self.focus_inspector(window, cx);
    }

    fn show_active_result_row_json(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some((item_id, _)) = self.focused_pane_results_item(cx) else {
            self.show_toast("Active tab has no result surface".into(), cx);
            return;
        };
        self.show_result_row_json(item_id, window, cx);
    }

    fn show_active_relation_definition(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some((item_id, _)) = self.focused_database_item(cx) else {
            self.show_toast("Active tab has no relation definition".into(), cx);
            return;
        };
        self.result_inspector_views
            .insert(item_id, ResultInspectorView::RelationDefinition);
        self.focus_inspector(window, cx);
    }

    fn copy_active_result_with_headers(&mut self, cx: &mut Context<Self>) {
        let Some(results) = self.focused_pane_results(cx) else {
            self.show_toast("Active tab has no result surface".into(), cx);
            return;
        };
        let copied = results.update(cx, |results, cx| {
            results.copy_selected_with_headers_to_clipboard(cx)
        });
        if !copied {
            self.show_toast("Highlight result fields before copying".into(), cx);
        }
    }

    fn focus_results(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(results) = self.focused_pane_results(cx) else {
            self.show_toast("Active tab has no result surface".into(), cx);
            return;
        };
        self.focused_surface = WorkspaceSurface::Results;
        results.update(cx, ResultsView::focus_data);
        results.focus_handle(cx).focus(window, cx);
        cx.notify();
    }

    fn go_to_context_line(&mut self, line: usize, window: &mut Window, cx: &mut Context<Self>) {
        let origin = self.command_palette_origin;
        self.dismiss_modal(&DismissModal, window, cx);
        if origin == WorkspaceSurface::Results {
            let Some(results) = self.focused_pane_results(cx) else {
                self.show_toast("Active tab has no data rows".into(), cx);
                return;
            };
            let found = results.update(cx, |results, cx| results.go_to_row_number(line, cx));
            if found {
                self.focused_surface = WorkspaceSurface::Results;
                results.focus_handle(cx).focus(window, cx);
            } else {
                self.show_toast(format!("Result row {line} is not loaded or visible"), cx);
            }
            return;
        }

        let Some(editor) = self.panes.get(self.active_pane).and_then(|pane| {
            let pane = pane.read(cx);
            pane.active_item().and_then(|item| pane.editor(item.id))
        }) else {
            self.show_toast("Active panel has no editor".into(), cx);
            return;
        };
        if editor.update(cx, |editor, cx| editor.go_to_line(line, cx)) {
            self.focused_surface = WorkspaceSurface::Editor;
            editor.focus_handle(cx).focus(window, cx);
        }
    }

    /// Restore the user's selected pane surface after temporary UI takes
    /// focus. Results stay active until Focus Editor is requested explicitly.
    fn restore_active_surface(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.focused_surface == WorkspaceSurface::Results
            && self.focused_pane_results(cx).is_some()
        {
            self.focus_results(window, cx);
        } else {
            self.focus_active_pane(window, cx);
        }
    }

    fn focus_tab_delta(&mut self, delta: isize, window: &mut Window, cx: &mut Context<Self>) {
        let Some(pane) = self.panes.get(self.active_pane) else {
            return;
        };
        let changed = pane.update(cx, |pane, _| {
            let Some(next) = pane.active_item.checked_add_signed(delta) else {
                return false;
            };
            if next >= pane.items.len() {
                return false;
            }
            pane.activate_item(next, true);
            true
        });
        if changed {
            self.restore_active_surface(window, cx);
            self.persist(cx);
            cx.notify();
        }
    }

    #[cfg(test)]
    fn active_editor_focused(&self, window: &Window, cx: &App) -> bool {
        self.panes
            .get(self.active_pane)
            .is_some_and(|pane| pane.read(cx).active_focus_handle(cx).is_focused(window))
    }

    #[cfg(test)]
    fn active_results_focused(&self, window: &Window, cx: &App) -> bool {
        self.panes.get(self.active_pane).is_some_and(|pane| {
            let pane = pane.read(cx);
            pane.active_item()
                .and_then(|item| pane.results.get(&item.id))
                .is_some_and(|results| results.focus_handle(cx).is_focused(window))
        })
    }

    fn on_pane_event(
        &mut self,
        emitter: &Entity<Pane>,
        event: &PaneEvent,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(index) = self.panes.iter().position(|pane| pane == emitter) else {
            return;
        };
        match event {
            PaneEvent::SetNotificationFilter { tone } => {
                emitter.update(cx, |pane, _| pane.notification_filter = *tone);
                self.sync_notifications_editor(cx);
                cx.notify();
            }
            PaneEvent::ClearNotifications => {
                self.notification_history.clear();
                self.unread_notifications = 0;
                self.sync_notifications_editor(cx);
                cx.notify();
            }
            PaneEvent::FocusRequested => {
                self.active_pane = index;
                // A child control may already have claimed focus while this
                // bubbled. Preserve it (notably the result grid); otherwise a
                // pane click restores the active editor after a modal.
                if !emitter.read(cx).focus_handle.contains_focused(window, cx) {
                    self.focus_active_pane(window, cx);
                } else {
                    let pane = emitter.read(cx);
                    self.focused_surface = if pane
                        .active_item()
                        .and_then(|item| pane.results.get(&item.id))
                        .is_some_and(|results| results.focus_handle(cx).is_focused(window))
                    {
                        WorkspaceSurface::Results
                    } else if pane
                        .active_item()
                        .is_some_and(|item| is_read_only_feed(item.kind))
                    {
                        WorkspaceSurface::Problems
                    } else {
                        WorkspaceSurface::Editor
                    };
                }
                if self.left_dock.presentation.open
                    && self.active_left_panel == LeftPanel::QueryOutline
                {
                    self.request_query_outline(cx);
                }
                cx.notify();
            }
            PaneEvent::DragPreviewActivated => {
                if let Some(previous) = self.active_tab_drop_pane.replace(emitter.clone()) {
                    if previous != *emitter {
                        previous.update(cx, |pane, cx| {
                            pane.tab_drop_target = None;
                            pane.tab_drag_preview_bounds = None;
                            pane.suppress_tab_drag_preview = false;
                            cx.notify();
                        });
                    }
                }
            }
            PaneEvent::TabBarDragEntered => {
                self.active_tab_bar_drag_bounds = emitter.read(cx).tab_bar_drag_bounds;
                self.set_root_tab_drop_target(None, cx);
            }
            PaneEvent::CommandRequested(command) => {
                self.active_pane = index;
                self.run_command(*command, window, cx);
            }
            PaneEvent::SplitRequested(direction) => {
                self.active_pane = index;
                self.split_pane_in_direction(*direction, window, cx);
            }
            PaneEvent::ToggleMaximizedRequested => {
                self.active_pane = index;
                let pane_id = emitter.read(cx).id;
                self.maximized_pane_id =
                    (self.maximized_pane_id != Some(pane_id)).then_some(pane_id);
                self.sync_pane_layout_view(cx);
                self.focus_active_pane(window, cx);
                cx.notify();
            }
            PaneEvent::CloseRequested => {
                self.active_pane = index;
                self.close_pane_at(index, window, cx);
            }
            PaneEvent::CloseItemRequested { item_id } => {
                self.active_pane = index;
                emitter.update(cx, |pane, _| {
                    if let Some(item_index) = pane.items.iter().position(|item| item.id == *item_id)
                    {
                        pane.activate_item(item_index, false);
                    }
                });
                self.close_active_item(&CloseActiveItem, window, cx);
            }
            PaneEvent::DiscardItemRequested { item_id } => {
                self.active_pane = index;
                emitter.update(cx, |pane, _| {
                    if let Some(item_index) = pane.items.iter().position(|item| item.id == *item_id)
                    {
                        pane.activate_item(item_index, false);
                    }
                });
                self.remove_active_item(window, cx);
            }
            PaneEvent::SaveItemRequested { item_id } => {
                self.active_pane = index;
                emitter.update(cx, |pane, _| {
                    if let Some(item_index) = pane.items.iter().position(|item| item.id == *item_id)
                    {
                        pane.activate_item(item_index, false);
                    }
                });
                self.save_active_item(&SaveActiveItem, window, cx);
            }
            PaneEvent::RenameItemRequested { item_id, name } => {
                self.active_pane = index;
                self.rename_query_item(emitter, *item_id, name, window, cx);
            }
            PaneEvent::SaveRunConfigurationRequested { item_id } => {
                self.active_pane = index;
                self.save_run_configuration(*item_id, cx);
            }
            PaneEvent::DeleteRunConfigurationRequested { item_id } => {
                self.active_pane = index;
                self.delete_run_configuration(*item_id, cx);
            }
            PaneEvent::RunConfigurationRequested { item_id } => {
                self.active_pane = index;
                self.run_configuration_from_editor(*item_id, cx);
            }
            PaneEvent::MoveItemRequested { item_id, target } => {
                // Match Zed's effect-cycle discipline: the drop callback only
                // records intent. Entity/tree mutations run after event
                // dispatch, when neither source nor target pane is borrowed.
                let emitter = emitter.clone();
                let item_id = *item_id;
                let target = *target;
                let root_target = if matches!(target, PaneDropTarget::Tab(_)) {
                    self.set_root_tab_drop_target(None, cx);
                    None
                } else {
                    self.root_tab_drop_target.take()
                };
                cx.defer_in(window, move |shell, window, cx| {
                    if let Some(root_target) = root_target {
                        shell.move_item_to_root(item_id, root_target, window, cx);
                    } else {
                        shell.move_item_to_target(emitter, item_id, target, window, cx);
                    }
                });
            }
            PaneEvent::EditorStateChanged { item_id, dirty } => {
                if let Some(dirty) = dirty {
                    emitter.update(cx, |pane, _| {
                        if let Some(item) = pane.items.iter_mut().find(|item| item.id == *item_id) {
                            item.dirty = *dirty;
                        }
                        if !*dirty && pane.pending_close_item == Some(*item_id) {
                            pane.pending_close_item = None;
                        }
                    });
                }
                cx.notify();
            }
            PaneEvent::RoomUpdateRequested { item_id, update } => {
                let document_id = emitter
                    .read(cx)
                    .room_document_source(*item_id)
                    .map(|source| source.document_id);
                if let (Some(sender), Some(document_id)) = (&self.room_document_sender, document_id)
                {
                    let generation = self
                        .room_document_generations
                        .entry(document_id)
                        .or_default();
                    *generation = generation.saturating_add(1);
                    let _ = sender.send(RoomDocumentCommand::Update {
                        document_id,
                        update: update.clone(),
                    });
                }
            }
            PaneEvent::OpenCommandPaletteRequested => {
                self.active_pane = index;
                self.open_command_palette(&OpenCommandPalette, window, cx);
            }
            PaneEvent::ExecuteRequested { item_id, sql } => {
                self.execute_database_item(*item_id, sql.clone(), cx)
            }
            PaneEvent::RefreshDatabaseItemRequested { item_id } => {
                self.refresh_database_item(*item_id, cx)
            }
            PaneEvent::OpenDatabaseDdlRequested { item_id } => {
                self.active_pane = index;
                self.open_database_item_ddl(*item_id, cx);
            }
            PaneEvent::LoadNextRowWindowRequested { item_id } => {
                self.load_next_row_window(*item_id, cx)
            }
            PaneEvent::OpenDataResultsRequested { item_id } => {
                self.active_pane = index;
                self.open_data_results_modal(emitter, *item_id, window, cx);
            }
            PaneEvent::ExportResultRequested {
                item_id,
                sql,
                format,
            } => self.prompt_result_export(*item_id, sql.clone(), *format, cx),
            PaneEvent::CancelResultExportRequested { item_id } => {
                if let Some(sender) = &self.executor_sender {
                    let _ = sender.send(ExecutorCommand::CancelResultExport { item_id: *item_id });
                    self.show_toast("Cancelling export…".into(), cx);
                }
            }
            PaneEvent::ApplyResultTransformRequested {
                item_id,
                sql,
                transform,
            } => self.apply_server_result_transform(*item_id, sql, transform.clone(), cx),
            PaneEvent::EditResultCellRequested { item_id } => {
                self.active_pane = index;
                self.open_result_cell_editor(emitter, *item_id, window, cx);
            }
            PaneEvent::PasteResultCellRequested { item_id, text } => {
                self.active_pane = index;
                self.paste_result_cell_range(emitter, *item_id, text, window, cx);
            }
            PaneEvent::RevertResultCellRequested { item_id } => {
                self.active_pane = index;
                self.revert_selected_result_cell(emitter, *item_id, window, cx);
            }
            PaneEvent::DeleteResultRowRequested { item_id } => {
                self.active_pane = index;
                self.stage_selected_result_row_delete(emitter, *item_id, window, cx);
            }
            PaneEvent::ReviewStagedResultEditsRequested { item_id } => {
                self.active_pane = index;
                self.open_staged_result_edits(*item_id, window, cx);
            }
            PaneEvent::SubmitResultCellEditRequested { item_id, text } => {
                self.submit_result_cell_edit(emitter, *item_id, text, window, cx);
            }
            PaneEvent::SubmitJsonResultEditRequested {
                item_id,
                text,
                preview,
            } => {
                self.submit_json_result_cell_edit(*item_id, text, *preview, window, cx);
            }
            PaneEvent::CancelResultCellEditRequested { item_id } => {
                self.cancel_result_cell_edit(emitter, *item_id, window, cx);
            }
            PaneEvent::ResultSelectionChanged => cx.notify(),
            PaneEvent::OpenResultRowJsonRequested { item_id } => {
                self.show_result_row_json(*item_id, window, cx)
            }
            PaneEvent::ReviewOutcomeUnknownRequested { item_id, sql } => {
                self.active_pane = index;
                self.modal = Some(Modal::ConfirmOutcomeUnknownRerun(*item_id, sql.clone()));
                self.focus_handle.focus(window, cx);
                cx.notify();
            }
            PaneEvent::CapturePlanRequested { item_id, sql } => {
                let params = match self.remembered_query_params(sql) {
                    Ok(params) => params,
                    Err(message) => {
                        self.show_error_toast(message, cx);
                        return;
                    }
                };
                if let Some(sender) = &self.executor_sender {
                    let source = self.versioned_execution_context(*item_id, cx);
                    let _ = sender.send(ExecutorCommand::CapturePlan {
                        item_id: *item_id,
                        sql: sql.clone(),
                        params,
                        source,
                    });
                    self.show_toast("Saving estimated plan capture…".into(), cx);
                }
            }
            PaneEvent::OpenPlanCapturesRequested { item_id, sql } => {
                let Some(source) = self.database_source(*item_id, cx) else {
                    return;
                };
                self.plan_capture_item = Some(*item_id);
                self.plan_capture_error = None;
                self.plan_capture_comparison = None;
                self.selected_plan_captures.clear();
                self.modal = Some(Modal::PlanCaptures);
                if let Some(sender) = &self.executor_sender {
                    let _ = sender.send(ExecutorCommand::LoadPlanCaptures {
                        item_id: *item_id,
                        tenant_id: source.tenant_id,
                        sql: sql.clone(),
                    });
                }
                cx.notify();
            }
            PaneEvent::ExplainRequested {
                item_id,
                sql,
                analyze,
            } => self.explain_database_item(*item_id, sql.clone(), *analyze, cx),
            PaneEvent::HistoryRequested { item_id, cursor } => {
                if let Some(sender) = &self.executor_sender {
                    if sender
                        .send(ExecutorCommand::LoadHistory {
                            item_id: *item_id,
                            cursor: cursor.clone(),
                        })
                        .is_err()
                    {
                        if let Some(results) = emitter.read(cx).results.get(item_id).cloned() {
                            results.update(cx, |results, cx| {
                                results.set_history_page(
                                    Err("Query history executor stopped".into()),
                                    cursor.is_some(),
                                    cx,
                                )
                            });
                        }
                    }
                } else if let Some(results) = emitter.read(cx).results.get(item_id).cloned() {
                    results.update(cx, |results, cx| {
                        results.set_history_page(
                            Err(
                                "Query history is unavailable until the desktop executor starts"
                                    .into(),
                            ),
                            cursor.is_some(),
                            cx,
                        )
                    });
                }
            }
            PaneEvent::RerunHistoryRequested { item_id, sql } => {
                self.execute_database_item(*item_id, sql.clone(), cx)
            }
            PaneEvent::SemanticRequested {
                item_id,
                revision,
                request,
            } => self.semantic_requested(*item_id, *revision, request.clone(), cx),
        }
    }

    fn move_item_to_target(
        &mut self,
        target_pane: Entity<Pane>,
        item_id: u64,
        target: PaneDropTarget,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(mut target_index) = self.panes.iter().position(|pane| pane == &target_pane) else {
            self.clear_tab_drag_previews(cx);
            cx.notify();
            return;
        };
        let Some(source_index) = self
            .panes
            .iter()
            .position(|pane| pane.read(cx).contains_item(item_id))
        else {
            self.clear_tab_drag_previews(cx);
            cx.notify();
            return;
        };
        let source_pane = self.panes[source_index].clone();
        let Some(transfer) = self.panes[source_index].update(cx, |pane, _| pane.take_item(item_id))
        else {
            self.clear_tab_drag_previews(cx);
            cx.notify();
            return;
        };
        let collapse_before_split = source_pane != target_pane
            && source_pane.read(cx).items.is_empty()
            && matches!(
                target,
                PaneDropTarget::Above
                    | PaneDropTarget::Before
                    | PaneDropTarget::After
                    | PaneDropTarget::Below
            );
        if collapse_before_split {
            self.remove_empty_source_pane(&source_pane, cx);
            let Some(index) = self.panes.iter().position(|pane| pane == &target_pane) else {
                self.clear_tab_drag_previews(cx);
                cx.notify();
                return;
            };
            target_index = index;
        }

        match target {
            PaneDropTarget::Center | PaneDropTarget::Tab(_) => {
                let insertion_index = match target {
                    PaneDropTarget::Tab(index) => Some(index),
                    _ => None,
                };
                target_pane.update(cx, |pane, cx| {
                    pane.receive_item(transfer, insertion_index, cx)
                });
                self.active_pane = target_index;
            }
            PaneDropTarget::Above
            | PaneDropTarget::Before
            | PaneDropTarget::After
            | PaneDropTarget::Below => {
                let target_id = target_pane.read(cx).id;
                let id = self.next_id;
                self.next_id += 1;
                let vim_mode = self.vim_mode_default();
                let pane = cx.new(|cx| {
                    Pane::from_presentation(
                        PanePresentation {
                            id,
                            items: Vec::new(),
                            active_item: 0,
                        },
                        vim_mode,
                        cx,
                    )
                });
                pane.update(cx, |pane, cx| pane.receive_item(transfer, None, cx));
                cx.subscribe_in(&pane, window, Self::on_pane_event).detach();

                let insertion_index =
                    if matches!(target, PaneDropTarget::Above | PaneDropTarget::Before) {
                        target_index
                    } else {
                        target_index + 1
                    };
                self.panes.insert(insertion_index, pane);
                pane_layout::split(
                    &mut self.pane_layout,
                    target_id,
                    id,
                    match target {
                        PaneDropTarget::Above => SplitDirection::Up,
                        PaneDropTarget::Before => SplitDirection::Left,
                        PaneDropTarget::After => SplitDirection::Right,
                        PaneDropTarget::Below => SplitDirection::Down,
                        PaneDropTarget::Center | PaneDropTarget::Tab(_) => unreachable!(),
                    },
                );
                self.active_pane = insertion_index;
            }
        }
        if !collapse_before_split {
            self.remove_empty_source_pane(&source_pane, cx);
        }
        self.sync_pane_layout_view(cx);
        self.clear_tab_drag_previews(cx);
        self.focus_active_pane(window, cx);
        self.persist(cx);
        cx.notify();
    }

    fn move_item_to_root(
        &mut self,
        item_id: u64,
        target: PaneDropTarget,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(source_index) = self
            .panes
            .iter()
            .position(|pane| pane.read(cx).contains_item(item_id))
        else {
            self.clear_tab_drag_previews(cx);
            cx.notify();
            return;
        };
        let source_pane = self.panes[source_index].clone();
        let Some(transfer) = source_pane.update(cx, |pane, _| pane.take_item(item_id)) else {
            self.clear_tab_drag_previews(cx);
            cx.notify();
            return;
        };
        if source_pane.read(cx).items.is_empty() && self.panes.len() == 1 {
            source_pane.update(cx, |pane, cx| pane.receive_item(transfer, None, cx));
            self.clear_tab_drag_previews(cx);
            self.focus_active_pane(window, cx);
            cx.notify();
            return;
        }
        self.remove_empty_source_pane(&source_pane, cx);

        let direction = match target {
            PaneDropTarget::Above => SplitDirection::Up,
            PaneDropTarget::Before => SplitDirection::Left,
            PaneDropTarget::After => SplitDirection::Right,
            PaneDropTarget::Below => SplitDirection::Down,
            PaneDropTarget::Center | PaneDropTarget::Tab(_) => return,
        };
        let id = self.next_id;
        self.next_id += 1;
        let vim_mode = self.vim_mode_default();
        let pane = cx.new(|cx| {
            Pane::from_presentation(
                PanePresentation {
                    id,
                    items: Vec::new(),
                    active_item: 0,
                },
                vim_mode,
                cx,
            )
        });
        pane.update(cx, |pane, cx| pane.receive_item(transfer, None, cx));
        cx.subscribe_in(&pane, window, Self::on_pane_event).detach();

        let insertion_index = if matches!(target, PaneDropTarget::Above | PaneDropTarget::Before) {
            0
        } else {
            self.panes.len()
        };
        self.panes.insert(insertion_index, pane);
        pane_layout::split_root(&mut self.pane_layout, id, direction);
        self.sync_pane_layout_view(cx);
        self.active_pane = insertion_index;
        self.clear_tab_drag_previews(cx);
        self.focus_active_pane(window, cx);
        self.persist(cx);
        cx.notify();
    }

    /// Moving a pane's sole tab should not strand an empty split. This also
    /// applies to edge drops on the source pane: the replacement pane inherits
    /// the full region after the empty source is removed.
    fn remove_empty_source_pane(&mut self, source: &Entity<Pane>, cx: &mut Context<Self>) {
        if self.panes.len() <= 1 {
            return;
        }
        let Some(index) = self.panes.iter().position(|pane| pane == source) else {
            return;
        };
        let pane = source.read(cx);
        if !pane.items.is_empty() {
            return;
        }
        let pane_id = pane.id;
        self.panes.remove(index);
        pane_layout::remove(&mut self.pane_layout, pane_id);
        if self.active_pane > index {
            self.active_pane -= 1;
        } else {
            self.active_pane = self.active_pane.min(self.panes.len() - 1);
        }
        self.sync_pane_layout_view(cx);
    }

    fn clear_tab_drag_previews(&mut self, cx: &mut Context<Self>) {
        self.active_tab_drop_pane = None;
        self.active_tab_bar_drag_bounds = None;
        self.set_root_tab_drop_target(None, cx);
        for pane in &self.panes {
            pane.update(cx, |pane, _| {
                pane.tab_drop_target = None;
                pane.tab_drag_preview_bounds = None;
                pane.suppress_tab_drag_preview = false;
                pane.tab_bar_drag_bounds = None;
            });
        }
    }

    fn set_root_tab_drop_target(&mut self, target: Option<PaneDropTarget>, cx: &mut Context<Self>) {
        if self.root_tab_drop_target == target {
            return;
        }
        self.root_tab_drop_target = target;
        let suppress = target.is_some();
        for pane in &self.panes {
            if pane.read(cx).suppress_tab_drag_preview != suppress {
                pane.update(cx, |pane, cx| {
                    pane.suppress_tab_drag_preview = suppress;
                    cx.notify();
                });
            }
        }
        cx.notify();
    }

    fn track_tab_drag(
        &mut self,
        event: &gpui::DragMoveEvent<TabDrag>,
        _: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(pane) = self.active_tab_drop_pane.clone() else {
            return;
        };
        let stale = pane
            .read(cx)
            .tab_drag_preview_bounds
            .is_some_and(|bounds| !bounds.contains(&event.event.position));
        if stale {
            pane.update(cx, |pane, cx| {
                pane.tab_drop_target = None;
                pane.tab_drag_preview_bounds = None;
                pane.suppress_tab_drag_preview = false;
                cx.notify();
            });
            self.active_tab_drop_pane = None;
        }
    }

    /// Workspace-edge targets split the entire pane group. Leaf-pane targets
    /// remain available away from the outer edge for nested corner splits.
    fn track_root_tab_drag(
        &mut self,
        event: &gpui::DragMoveEvent<TabDrag>,
        _: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let over_tab_bar = self
            .active_tab_bar_drag_bounds
            .is_some_and(|bounds| bounds.contains(&event.event.position));
        if !over_tab_bar {
            self.active_tab_bar_drag_bounds = None;
        }
        let target = if over_tab_bar
            || self.panes.len() <= 1
            || !event.bounds.contains(&event.event.position)
        {
            None
        } else {
            let relative_x = event.event.position.x - event.bounds.left();
            let relative_y = event.event.position.y - event.bounds.top();
            let width = event.bounds.size.width;
            let height = event.bounds.size.height;
            let edge = px(ROOT_PANE_DROP_TARGET_SIZE);
            let distances = [
                (relative_y, PaneDropTarget::Above),
                (width - relative_x, PaneDropTarget::After),
                (height - relative_y, PaneDropTarget::Below),
                (relative_x, PaneDropTarget::Before),
            ];
            distances
                .into_iter()
                .min_by_key(|(distance, _)| *distance)
                .filter(|(distance, _)| *distance < edge)
                .map(|(_, target)| target)
        };
        self.set_root_tab_drop_target(target, cx);
    }

    fn finish_workspace_tab_drag(&mut self, _: &TabDrag, _: &mut Window, cx: &mut Context<Self>) {
        self.clear_tab_drag_previews(cx);
    }

    /// Remove a pane and keep the workspace non-empty. The final pane is never
    /// destroyed; it degrades to an empty pane the user can reuse.
    fn close_pane_at(&mut self, index: usize, window: &mut Window, cx: &mut Context<Self>) {
        if self.panes.len() <= 1 || index >= self.panes.len() {
            self.persist(cx);
            cx.notify();
            return;
        }
        let removed_pane_id = self.panes[index].read(cx).id;
        self.panes.remove(index);
        pane_layout::remove(&mut self.pane_layout, removed_pane_id);
        self.sync_pane_layout_view(cx);
        self.active_pane = self.active_pane.min(self.panes.len() - 1);
        self.focus_active_pane(window, cx);
        self.persist(cx);
        cx.notify();
    }

    fn close_active_pane(
        &mut self,
        _: &CloseActivePane,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(target) = self.panes.get(self.active_pane).cloned() else {
            return;
        };
        while let Some(pane_index) = self.panes.iter().position(|pane| pane == &target) {
            let clean_item = target.read(cx).items.iter().position(|item| !item.dirty);
            let Some(item_index) = clean_item else {
                break;
            };
            self.active_pane = pane_index;
            target.update(cx, |pane, _| pane.activate_item(item_index, false));
            self.remove_active_item(window, cx);
        }
        if let Some(pane_index) = self.panes.iter().position(|pane| pane == &target) {
            self.active_pane = pane_index;
            let dirty_count = target
                .read(cx)
                .items
                .iter()
                .filter(|item| item.dirty)
                .count();
            if dirty_count > 0 {
                self.show_toast(
                    format!("Kept {dirty_count} tab(s) with unsaved changes"),
                    cx,
                );
                self.focus_active_pane(window, cx);
            }
        }
    }

    fn focus_next_pane(&mut self, _: &FocusNextPane, window: &mut Window, cx: &mut Context<Self>) {
        self.active_pane = (self.active_pane + 1) % self.panes.len();
        self.restore_active_surface(window, cx);
        cx.notify();
    }

    fn focus_pane_direction(
        &mut self,
        direction: SplitDirection,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(active_id) = self
            .panes
            .get(self.active_pane)
            .map(|pane| pane.read(cx).id)
        else {
            return;
        };
        let Some(neighbor_id) = pane_layout::neighbor(&self.pane_layout, active_id, direction)
        else {
            return;
        };
        let Some(index) = self
            .panes
            .iter()
            .position(|pane| pane.read(cx).id == neighbor_id)
        else {
            return;
        };
        self.active_pane = index;
        self.restore_active_surface(window, cx);
        cx.notify();
    }

    fn close_active_item(
        &mut self,
        _: &CloseActiveItem,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(pane) = self.panes.get(self.active_pane) else {
            return;
        };
        if let Some(item) = pane.read(cx).active_item() {
            if item.dirty {
                let item_id = item.id;
                pane.update(cx, |pane, _| {
                    pane.pending_close_item = Some(item_id);
                });
                cx.notify();
                return;
            }
        }
        self.remove_active_item(window, cx);
    }

    fn remove_active_item(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let removed_document_id = self.panes.get(self.active_pane).and_then(|pane| {
            let pane = pane.read(cx);
            pane.active_item()
                .and_then(|item| pane.room_document_source(item.id))
                .map(|source| source.document_id)
        });
        let removed_item_id = self.panes.get(self.active_pane).and_then(|pane| {
            pane.update(cx, |pane, _| {
                if !pane.items.is_empty() {
                    let removed = pane.items.remove(pane.active_item);
                    pane.forget_item(removed.id);
                    pane.active_item = pane.active_item.min(pane.items.len().saturating_sub(1));
                    Some(removed.id)
                } else {
                    None
                }
            })
        });
        if let Some(item_id) = removed_item_id {
            self.clear_global_problems_for(item_id, cx);
            self.table_definitions.remove(&item_id);
            self.table_definition_sections.remove(&item_id);
            self.running_explains.remove(&item_id);
            if self
                .pending_database_explain
                .as_ref()
                .is_some_and(|pending| pending.item_id == item_id)
            {
                self.pending_database_explain = None;
            }
            self.pending_object_ddl.remove(&item_id);
            if self
                .table_designer
                .as_ref()
                .is_some_and(|designer| designer.item_id == item_id)
            {
                self.table_designer = None;
                self.modal = None;
            }
        }
        if let Some(item_id) = removed_item_id {
            self.held_result_pages.remove(&item_id);
            self.theme_items.remove(&item_id);
        }
        if let (Some(sender), Some(item_id)) = (&self.executor_sender, removed_item_id) {
            self.semantic_analyze_generation.remove(&item_id);
            let _ = sender.send(ExecutorCommand::CloseSemanticDocument { item_id });
        }
        if let (Some(sender), Some(document_id)) = (&self.room_document_sender, removed_document_id)
        {
            let _ = sender.send(RoomDocumentCommand::Close { document_id });
        }
        // A pane emptied by its last close collapses so panes never accumulate
        // as un-closeable ghosts. The final pane always survives.
        let emptied = self
            .panes
            .get(self.active_pane)
            .is_some_and(|pane| pane.read(cx).items.is_empty());
        if emptied && self.panes.len() > 1 {
            self.close_pane_at(self.active_pane, window, cx);
        } else {
            // The closed item's editor may have held focus; move it to the new
            // active item so keyboard input keeps routing.
            self.focus_active_pane(window, cx);
            self.persist(cx);
            cx.notify();
        }
    }

    fn save_active_item(
        &mut self,
        _: &SaveActiveItem,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let active_json = self.panes.get(self.active_pane).and_then(|pane| {
            let pane = pane.read(cx);
            let item_id = pane.active_item()?.id;
            (pane.database_item_views.get(&item_id) == Some(&DatabaseItemView::Json))
                .then(|| {
                    pane.editor(item_id)
                        .map(|editor| (item_id, editor.read(cx).document().text().to_owned()))
                })
                .flatten()
        });
        if let Some((item_id, text)) = active_json {
            self.submit_json_result_cell_edit(item_id, &text, false, window, cx);
            return;
        }
        let active_data_item = (self.focused_surface == WorkspaceSurface::Results)
            .then(|| {
                let pane = self.panes.get(self.active_pane)?.read(cx);
                let item_id = pane.active_item()?.id;
                pane.results
                    .get(&item_id)
                    .is_some_and(|results| results.read(cx).active_tab() == ResultTab::Data)
                    .then_some(item_id)
            })
            .flatten();
        if let Some(item_id) = active_data_item {
            if self.staged_result_item_id() != Some(item_id) {
                self.show_toast("No table changes are staged".into(), cx);
                self.focus_results(window, cx);
                return;
            }
            self.focus_results(window, cx);
            self.apply_result_cell_edit(cx);
            return;
        }
        let active_query_source = self.panes.get(self.active_pane).and_then(|pane| {
            let pane = pane.read(cx);
            pane.active_item()
                .filter(|item| item.kind == ItemKind::Query)
                .map(|item| item.source.clone())
        });
        if let Some(source) = active_query_source {
            if matches!(source, Some(ItemSource::RoomDocument(_))) {
                self.show_toast("Room queries save automatically".into(), cx);
            } else {
                self.save_active_query(cx);
            }
            return;
        }
        let active_run_configuration = self.panes.get(self.active_pane).and_then(|pane| {
            let pane = pane.read(cx);
            pane.active_item()
                .filter(|item| item.kind == ItemKind::RunConfiguration)
                .map(|item| item.id)
        });
        if let Some(item_id) = active_run_configuration {
            self.save_run_configuration(item_id, cx);
            return;
        }
        let active_configuration = self.panes.get(self.active_pane).and_then(|pane| {
            let pane = pane.read(cx);
            pane.active_item()
                .filter(|item| item.kind == ItemKind::Configuration)
                .and_then(|item| pane.editor(item.id).map(|editor| (item.id, editor)))
        });
        if let Some((item_id, editor)) = active_configuration {
            if let Some(theme_id) = self.theme_items.get(&item_id).cloned() {
                let Some(store) = self.settings_store.clone() else {
                    self.show_toast("Themes are unavailable in this session".into(), cx);
                    return;
                };
                let source = editor.read(cx).document().text().to_owned();
                match store.save_theme_text(&theme_id, &source) {
                    Ok(theme) => {
                        if self.settings.appearance.theme == theme_id {
                            self.dark_theme = theme.appearance == ThemeAppearance::Dark;
                            sift_ui::set_theme(theme, cx);
                        }
                        if let Some(pane) = self.panes.get(self.active_pane) {
                            pane.update(cx, |pane, cx| pane.mark_clean(item_id, cx));
                        }
                        self.show_toast(format!("Saved {theme_id}.toml"), cx);
                    }
                    Err(error) => self.show_toast(error, cx),
                }
                self.focus_active_pane(window, cx);
                cx.notify();
                return;
            }
            if self.keymaps_item == Some(item_id) {
                let Some(store) = self.settings_store.clone() else {
                    self.show_toast("keymaps.json is unavailable in this session".into(), cx);
                    return;
                };
                let source = editor.read(cx).document().text().to_owned();
                match KeymapSettings::decode(&source).and_then(|keymaps| {
                    validate_keymap_commands(&keymaps)?;
                    store.save_keymaps_text(&source)?;
                    Ok(keymaps)
                }) {
                    Ok(keymaps) => {
                        self.keymaps = keymaps.clone();
                        self.invalidate_command_projection();
                        self.sync_keymap_inputs(&keymaps, cx);
                        if let Some(pane) = self.panes.get(self.active_pane) {
                            pane.update(cx, |pane, cx| pane.mark_clean(item_id, cx));
                        }
                        self.show_toast("Saved keymaps.json".into(), cx);
                    }
                    Err(error) => self.show_toast(error, cx),
                }
                self.focus_active_pane(window, cx);
                cx.notify();
                return;
            }
            if self.settings_item == Some(item_id) {
                let Some(store) = self.settings_store.clone() else {
                    self.show_toast(
                        "The settings file is unavailable in this session".into(),
                        cx,
                    );
                    return;
                };
                match store.save_text(editor.read(cx).document().text()) {
                    Ok(settings) => {
                        let theme = store
                            .load_theme(&settings.appearance.theme)
                            .expect("save_text validates the selected theme");
                        self.dark_theme = theme.appearance == ThemeAppearance::Dark;
                        sift_ui::set_theme(theme, cx);
                        self.settings = settings;
                        self.sync_editor_keymaps_to_profile(cx);
                        self.sync_selection_aggregate_setting(cx);
                        if let Some(pane) = self.panes.get(self.active_pane) {
                            pane.update(cx, |pane, cx| pane.mark_clean(item_id, cx));
                        }
                        self.show_toast("Saved settings.toml".into(), cx);
                    }
                    Err(error) => self.show_toast(error, cx),
                }
                self.focus_active_pane(window, cx);
                cx.notify();
                return;
            }
            self.instance_configuration_editor = editor;
            self.save_instance_configuration(cx);
            return;
        }
        let active_room_document = self.panes.get(self.active_pane).and_then(|pane| {
            let pane = pane.read(cx);
            let item = pane.active_item()?;
            match item.source.as_ref()? {
                ItemSource::RoomDocument(source) => Some(source.document_id),
                ItemSource::DatabaseObject(_) | ItemSource::SavedQuery(_) => None,
            }
        });
        if let Some(document_id) = active_room_document {
            self.flush_room_document(document_id);
            self.show_toast("Saving canonical workspace document…".into(), cx);
            self.focus_active_pane(window, cx);
            return;
        }
        if let Some(pane) = self.panes.get(self.active_pane) {
            pane.update(cx, |pane, cx| {
                if let Some(item_id) = pane.active_item().map(|item| item.id) {
                    pane.mark_clean(item_id, cx);
                    pane.pending_close_item = None;
                }
            });
        }
        self.show_toast("Presentation saved".into(), cx);
        self.persist(cx);
        self.focus_active_pane(window, cx);
        cx.notify();
    }

    fn flush_room_document(&self, document_id: i64) {
        let Some(sender) = &self.room_document_sender else {
            return;
        };
        let generation = self
            .room_document_generations
            .get(&document_id)
            .copied()
            .unwrap_or_default();
        let _ = sender.send(RoomDocumentCommand::Flush {
            document_id,
            generation,
        });
    }

    fn save_all_workspace_documents(&mut self, cx: &mut Context<Self>) {
        let document_ids = self
            .panes
            .iter()
            .flat_map(|pane| pane.read(cx).items.clone())
            .filter_map(|item| match item.source {
                Some(ItemSource::RoomDocument(source)) => Some(source.document_id),
                _ => None,
            })
            .collect::<HashSet<_>>();
        if document_ids.is_empty() {
            self.show_toast("No workspace documents are open".into(), cx);
            return;
        }
        for document_id in &document_ids {
            self.flush_room_document(*document_id);
        }
        self.show_toast(
            format!("Saving {} workspace document(s)…", document_ids.len()),
            cx,
        );
    }

    fn open_command_palette(
        &mut self,
        _: &OpenCommandPalette,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.open_command_palette_with_query("", window, cx);
    }

    fn open_command_palette_with_query(
        &mut self,
        query: &str,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.ide_input = None;
        self.command_palette_origin = self.focused_surface;
        self.modal = Some(Modal::CommandPalette);
        self.palette_selected = 0;
        self.query_input
            .update(cx, |input, cx| input.set_text(query, cx));
        self.palette_scroll_handle
            .scroll_to_item(0, ScrollStrategy::Top);
        self.query_input.focus_handle(cx).focus(window, cx);
        cx.notify();
    }

    fn open_saved_query_search(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.selected_tenant_id().is_none() {
            self.show_toast("No tenant is available".into(), cx);
            return;
        }
        self.open_command_palette_with_query("?", window, cx);
    }

    fn open_schema_search_action(
        &mut self,
        _: &OpenSchemaSearch,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.open_schema_search(window, cx);
    }

    fn intercept_ide_input(
        &mut self,
        event: &KeystrokeEvent,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let key = event.keystroke.unparse();
        if self.modal == Some(Modal::CommandPalette)
            && key == "enter"
            && !event.keystroke.modifiers.modified()
        {
            self.palette_confirm(&PaletteConfirm, window, cx);
            cx.stop_propagation();
            return;
        }
        let repository_modal = matches!(
            self.modal,
            Some(Modal::RepositoryBranches | Modal::RepositoryHistory)
        );
        if repository_modal && !event.keystroke.modifiers.modified() {
            let text_input_focused = event
                .context_stack
                .iter()
                .any(|context| context.contains("SiftTextInput"));
            if text_input_focused && key == "escape" {
                self.focus_handle.focus(window, cx);
                cx.stop_propagation();
                return;
            }
            if !text_input_focused {
                let row_count = self.repository_modal_row_count(cx);
                let handled = match key.as_str() {
                    "j" if row_count > 0 => {
                        self.repository_modal_selected =
                            (self.repository_modal_selected + 1).min(row_count - 1);
                        true
                    }
                    "k" if row_count > 0 => {
                        self.repository_modal_selected =
                            self.repository_modal_selected.saturating_sub(1);
                        true
                    }
                    "g" if self.repository_modal_g_pending => {
                        self.repository_modal_g_pending = false;
                        self.repository_modal_selected = 0;
                        true
                    }
                    "g" => {
                        self.repository_modal_g_pending = true;
                        true
                    }
                    "shift-g" if row_count > 0 => {
                        self.repository_modal_g_pending = false;
                        self.repository_modal_selected = row_count - 1;
                        true
                    }
                    "enter" if row_count > 0 => {
                        self.activate_repository_modal_row(cx);
                        true
                    }
                    "/" => {
                        self.query_input.read(cx).focus_handle(cx).focus(window, cx);
                        true
                    }
                    "escape" => {
                        self.dismiss_modal(&DismissModal, window, cx);
                        true
                    }
                    _ => {
                        self.repository_modal_g_pending = false;
                        false
                    }
                };
                if handled {
                    cx.stop_propagation();
                    cx.notify();
                    return;
                }
            }
        }
        if self.ide_input.is_none() {
            if !self.keyboard_profile().vim_enabled() {
                return;
            }
            let has_context = |name: &str| {
                event
                    .context_stack
                    .iter()
                    .any(|context| context.contains(name))
            };
            let vim_normal = event.context_stack.iter().any(|context| {
                context
                    .get("vim_mode")
                    .is_some_and(|mode| mode.as_ref() == "normal")
            });
            let vim_visual = event.context_stack.iter().any(|context| {
                context
                    .get("vim_mode")
                    .is_some_and(|mode| mode.as_ref() == "visual")
            });
            let workspace = has_context("SiftWorkspace");
            let editor = has_context("SiftEditor");
            let results = has_context("SiftResults");
            let text_input = has_context("SiftTextInput");
            let modal = has_context("SiftModal");
            let git_diff = self.panes.get(self.active_pane).is_some_and(|pane| {
                pane.read(cx)
                    .active_item()
                    .is_some_and(|item| item.kind == ItemKind::GitDiff)
            });

            if workspace && git_diff && (vim_normal || vim_visual) && !modal && !text_input {
                let handled = match (self.repository_diff_prefix, key.as_str()) {
                    (None, "s") if vim_visual => {
                        self.set_active_repository_lines_staged(RepositoryIndexAction::Stage, cx);
                        true
                    }
                    (None, "u") if vim_visual => {
                        self.set_active_repository_lines_staged(RepositoryIndexAction::Unstage, cx);
                        true
                    }
                    (_, "[") => {
                        self.repository_diff_prefix = Some(-1);
                        true
                    }
                    (_, "]") => {
                        self.repository_diff_prefix = Some(1);
                        true
                    }
                    (Some(delta), "c") => {
                        self.repository_diff_prefix = None;
                        self.navigate_active_diff_hunk(delta, cx);
                        true
                    }
                    (Some(delta), "f") => {
                        self.repository_diff_prefix = None;
                        self.navigate_repository_file(delta, cx);
                        true
                    }
                    (Some(_), "escape") => {
                        self.repository_diff_prefix = None;
                        cx.notify();
                        true
                    }
                    (Some(_), _) => {
                        self.repository_diff_prefix = None;
                        false
                    }
                    (None, "s") => {
                        self.set_active_repository_hunk_staged(
                            RepositoryIndexAction::Stage,
                            HunkNavigation::Stay,
                            cx,
                        );
                        true
                    }
                    (None, "u") => {
                        self.set_active_repository_hunk_staged(
                            RepositoryIndexAction::Unstage,
                            HunkNavigation::Stay,
                            cx,
                        );
                        true
                    }
                    (None, "shift-s") => {
                        self.set_active_repository_hunk_staged(
                            RepositoryIndexAction::Stage,
                            HunkNavigation::Next,
                            cx,
                        );
                        true
                    }
                    (None, "shift-u") => {
                        self.set_active_repository_hunk_staged(
                            RepositoryIndexAction::Unstage,
                            HunkNavigation::Next,
                            cx,
                        );
                        true
                    }
                    (None, _) => false,
                };
                if handled {
                    cx.stop_propagation();
                    return;
                }
            }

            if workspace && results && !modal && !text_input && key == ":" {
                // Result focus can move without a Pane focus event. Capture the
                // actual keystroke context so `:w` does not fall back to the
                // editor after the command palette temporarily takes focus.
                self.focused_surface = WorkspaceSurface::Results;
                self.open_command_palette(&OpenCommandPalette, window, cx);
                cx.stop_propagation();
                return;
            }

            if self.pane_input {
                cx.stop_propagation();
                self.pane_input = false;
                match key.as_str() {
                    "h" => self.focus_pane_direction(SplitDirection::Left, window, cx),
                    "j" => self.focus_pane_direction(SplitDirection::Down, window, cx),
                    "k" => self.focus_pane_direction(SplitDirection::Up, window, cx),
                    "l" => self.focus_pane_direction(SplitDirection::Right, window, cx),
                    "escape" => cx.notify(),
                    _ => self.show_toast(format!("Unknown pane command: Ctrl+W {key}"), cx),
                }
                return;
            }

            if workspace
                && !modal
                && !text_input
                && (self.keyboard_profile() == KeyboardProfile::Vim || vim_normal || !editor)
                && key == "ctrl-w"
            {
                self.pane_input = true;
                cx.stop_propagation();
                cx.notify();
                return;
            }

            if workspace && !modal && !text_input && has_context("SiftConnections") {
                let handled = match key.as_str() {
                    "j" => {
                        self.move_connection_selection(1, cx);
                        true
                    }
                    "k" => {
                        self.move_connection_selection(-1, cx);
                        true
                    }
                    "h" => {
                        self.connection_nav_g_pending = false;
                        self.collapse_connection_item(cx);
                        true
                    }
                    "l" => {
                        self.connection_nav_g_pending = false;
                        self.expand_connection_item(cx);
                        true
                    }
                    "enter" => {
                        self.connection_nav_g_pending = false;
                        self.activate_connection_item(window, cx);
                        true
                    }
                    "d" => {
                        self.connection_nav_g_pending = false;
                        self.open_selected_schema_object_ddl(window, cx);
                        true
                    }
                    "p" => {
                        self.connection_nav_g_pending = false;
                        self.preview_selected_schema_object(window, cx);
                        true
                    }
                    "ctrl-f" => {
                        self.connection_nav_g_pending = false;
                        self.open_connections_find(window, cx);
                        true
                    }
                    "/" => {
                        self.connection_nav_g_pending = false;
                        self.open_schema_search(window, cx);
                        true
                    }
                    "r" => {
                        self.connection_nav_g_pending = false;
                        self.refresh_connection_schema(cx);
                        true
                    }
                    "g" if self.connection_nav_g_pending => {
                        self.connection_nav_g_pending = false;
                        self.connection_nav_selected = 0;
                        cx.notify();
                        true
                    }
                    "g" => {
                        self.connection_nav_g_pending = true;
                        cx.notify();
                        true
                    }
                    "shift-g" => {
                        self.connection_nav_g_pending = false;
                        self.connection_nav_selected =
                            self.visible_connection_items().len().saturating_sub(1);
                        cx.notify();
                        true
                    }
                    "escape" => {
                        self.focus_active_pane(window, cx);
                        cx.notify();
                        true
                    }
                    _ => {
                        self.connection_nav_g_pending = false;
                        false
                    }
                };
                if handled {
                    cx.stop_propagation();
                    return;
                }
            }
            if workspace && !modal && !text_input && has_context("SiftGit") {
                let handled = match key.as_str() {
                    "j" => {
                        self.navigate_repository_file(1, cx);
                        true
                    }
                    "k" => {
                        self.navigate_repository_file(-1, cx);
                        true
                    }
                    "g" if self.repository_nav_g_pending => {
                        self.repository_nav_g_pending = false;
                        self.repository.select_edge(false);
                        self.repository_scroll_handle
                            .scroll_to_item(0, ScrollStrategy::Top);
                        cx.notify();
                        true
                    }
                    "g" => {
                        self.repository_nav_g_pending = true;
                        cx.notify();
                        true
                    }
                    "shift-g" => {
                        self.repository_nav_g_pending = false;
                        self.repository.select_edge(true);
                        if let Some(index) = self.repository.selected_row_index() {
                            self.repository_scroll_handle
                                .scroll_to_item(index, ScrollStrategy::Bottom);
                        }
                        cx.notify();
                        true
                    }
                    "enter" => {
                        self.repository_nav_g_pending = false;
                        self.open_selected_repository_change(cx);
                        true
                    }
                    "space" => {
                        self.toggle_selected_repository_path_staged(cx);
                        true
                    }
                    "a" => {
                        let paths = self.repository.stageable_paths();
                        self.set_repository_paths_staged(paths, RepositoryIndexAction::Stage, cx);
                        true
                    }
                    "c" => {
                        self.repository_commit_input
                            .read(cx)
                            .focus_handle(cx)
                            .focus(window, cx);
                        true
                    }
                    "o" => {
                        self.open_selected_repository_file(window, cx);
                        true
                    }
                    "v" => {
                        self.request_selected_repository_diff(cx);
                        true
                    }
                    "s" => {
                        self.set_selected_repository_path_staged(RepositoryIndexAction::Stage, cx);
                        true
                    }
                    "u" => {
                        self.set_selected_repository_path_staged(
                            RepositoryIndexAction::Unstage,
                            cx,
                        );
                        true
                    }
                    "d" => {
                        if let Some(path) = self.repository.selected_path().cloned() {
                            self.modal = Some(Modal::ConfirmRepositoryDiscard(path));
                            cx.notify();
                        }
                        true
                    }
                    "r" => {
                        self.request_repository_status(cx);
                        true
                    }
                    "/" => {
                        self.open_repository_filter(window, cx);
                        true
                    }
                    "escape" => {
                        self.repository_nav_g_pending = false;
                        self.focus_active_pane(window, cx);
                        true
                    }
                    _ => {
                        self.repository_nav_g_pending = false;
                        false
                    }
                };
                if handled {
                    cx.stop_propagation();
                    return;
                }
            }
            if workspace && !modal && !text_input && has_context("SiftInspector") {
                let inspector_view = self
                    .focused_pane_results_item(cx)
                    .map(|(item_id, _)| {
                        self.result_inspector_views
                            .get(&item_id)
                            .copied()
                            .unwrap_or_default()
                    })
                    .unwrap_or_default();
                let fields_selected = inspector_view == ResultInspectorView::Fields;
                let handled = match key.as_str() {
                    "h" => self.move_result_inspector_view(-1, cx),
                    "l" => self.move_result_inspector_view(1, cx),
                    "1" => self.select_result_inspector_view(ResultInspectorView::Fields, cx),
                    "2" => self.select_result_inspector_view(ResultInspectorView::Value, cx),
                    "3" => self.select_result_inspector_view(ResultInspectorView::RowJson, cx),
                    "4" => self
                        .select_result_inspector_view(ResultInspectorView::RelationDefinition, cx),
                    "j" if fields_selected => self.move_inspector_field_selection(1, cx),
                    "k" if fields_selected => self.move_inspector_field_selection(-1, cx),
                    "g" if fields_selected && self.inspector_g_pending => {
                        self.inspector_field_selected = 0;
                        self.inspector_g_pending = false;
                        cx.notify();
                        true
                    }
                    "g" if fields_selected => {
                        self.inspector_g_pending = true;
                        cx.notify();
                        true
                    }
                    "shift-g" if fields_selected => {
                        self.move_inspector_field_selection(isize::MAX, cx)
                    }
                    "enter" | "space" if fields_selected => {
                        self.toggle_selected_inspector_field(cx)
                    }
                    "a" if fields_selected => self.set_all_inspector_fields(true, cx),
                    "n" if fields_selected => self.set_all_inspector_fields(false, cx),
                    "f" if inspector_view == ResultInspectorView::RowJson => {
                        self.toggle_inspector_row_json_fold(cx)
                    }
                    "w" if inspector_view == ResultInspectorView::RowJson => {
                        self.toggle_inspector_row_json_wrap(cx)
                    }
                    "/" if inspector_view == ResultInspectorView::RowJson => {
                        self.focus_inspector_row_json_filter(window, cx)
                    }
                    "y" if inspector_view != ResultInspectorView::Fields => {
                        self.copy_inspector_selection(cx)
                    }
                    "escape" => {
                        self.inspector_g_pending = false;
                        self.focus_active_pane(window, cx);
                        cx.notify();
                        true
                    }
                    _ => {
                        self.inspector_g_pending = false;
                        false
                    }
                };
                if handled {
                    cx.stop_propagation();
                    return;
                }
            }
            let starts_ide_command = workspace
                && !modal
                && ((key == "space"
                    && (vim_normal
                        || self.focused_surface == WorkspaceSurface::Problems
                        || (!editor && !text_input)))
                    || (key == "ctrl-k" && !text_input));
            if !starts_ide_command {
                return;
            }
            self.ide_input = Some(Vec::new());
            cx.stop_propagation();
            cx.notify();
            return;
        }

        cx.stop_propagation();
        if key == "escape" {
            self.ide_input = None;
            cx.notify();
            return;
        }
        if key == "backspace" {
            let keys = self.ide_input.as_mut().expect("IDE command is active");
            if keys.pop().is_none() {
                self.ide_input = None;
            }
            cx.notify();
            return;
        }

        let plain_key = event.keystroke.modifiers.number_of_modifiers() == 0
            && key.chars().count() == 1
            && key
                .chars()
                .all(|character| character.is_ascii_alphanumeric());
        if !plain_key {
            let entered = self.ide_key_buffer();
            self.ide_input = None;
            self.show_toast(format!("Unknown IDE command: {entered} {key}"), cx);
            return;
        }

        let keys = self.ide_input.as_mut().expect("IDE command is active");
        keys.push(key);
        match CommandRegistry::resolve_language_with(keys, &self.keymaps.bindings) {
            CommandLanguageMatch::Prefix => cx.notify(),
            CommandLanguageMatch::Command(command) => {
                self.ide_input = None;
                let spec = self.command_spec(command, cx);
                if let Some(reason) = spec.disabled_reason {
                    self.show_toast(format!("{}: {reason}", spec.label), cx);
                } else {
                    self.run_command(command, window, cx);
                }
            }
            CommandLanguageMatch::Invalid => {
                let entered = self.ide_key_buffer();
                self.ide_input = None;
                self.show_toast(format!("Unknown IDE command: {entered}"), cx);
            }
        }
    }

    fn ide_key_buffer(&self) -> String {
        if self.pane_input {
            return "Ctrl+W".into();
        }
        match self.ide_input.as_deref() {
            Some([]) => "<leader>".into(),
            Some(keys) => format!("<leader> {}", keys.join(" ")),
            None => String::new(),
        }
    }

    fn open_schema_search(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if !matches!(self.connection_status, ConnectionStatus::Connected { .. }) {
            self.show_toast(
                "Connect to a database before searching its schema".into(),
                cx,
            );
            return;
        }
        self.open_command_palette_with_query("@", window, cx);
    }

    fn open_data_search(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if !matches!(self.connection_status, ConnectionStatus::Connected { .. }) {
            self.show_toast(
                "Connect to a database before searching table data".into(),
                cx,
            );
            return;
        }
        if self.searchable_tables().is_empty() {
            self.show_toast("Refresh the schema before searching table data".into(), cx);
            return;
        }
        self.open_command_palette_with_query("$", window, cx);
    }

    fn capture_catalog_snapshot(&mut self, cx: &mut Context<Self>) {
        let Some(sender) = &self.executor_sender else {
            return;
        };
        if sender.send(ExecutorCommand::CaptureCatalogSnapshot).is_ok() {
            self.show_toast("Capturing schema baseline…".into(), cx);
        }
    }

    fn load_catalog_snapshots(&mut self, cx: &mut Context<Self>) {
        let Some(sender) = &self.executor_sender else {
            return;
        };
        if sender.send(ExecutorCommand::LoadCatalogSnapshots).is_ok() {
            self.catalog_snapshots_loading = true;
            self.catalog_snapshots_error = None;
            cx.notify();
        }
    }

    fn open_catalog_snapshots(&mut self, cx: &mut Context<Self>) {
        self.modal = Some(Modal::CatalogSnapshots);
        self.load_catalog_snapshots(cx);
    }

    fn select_catalog_snapshot(
        &mut self,
        snapshot: sift_protocol::CatalogSnapshotId,
        cx: &mut Context<Self>,
    ) {
        self.selected_catalog_snapshot = Some(snapshot);
        cx.notify();
    }

    fn open_catalog_diagram(&mut self, cx: &mut Context<Self>) {
        if !self.require_operation(
            sift_protocol::OperationKind::ProjectCatalogDiagram,
            "Open catalog diagram",
            cx,
        ) {
            return;
        }
        let Some(sender) = &self.executor_sender else {
            self.show_error_toast("Connect before opening the catalog diagram".into(), cx);
            return;
        };
        if sender.send(ExecutorCommand::LoadCatalogDiagram).is_ok() {
            self.catalog_diagram.start_loading();
            self.modal = Some(Modal::CatalogDiagram);
            cx.notify();
        }
    }

    fn prepare_catalog_migration(&mut self, cx: &mut Context<Self>) {
        let Some(sender) = &self.executor_sender else {
            return;
        };
        if sender
            .send(ExecutorCommand::PrepareCatalogMigration {
                baseline: self.selected_catalog_snapshot,
            })
            .is_ok()
        {
            self.catalog_diff = None;
            self.catalog_migration_plan = None;
            self.catalog_migration_error = None;
            self.catalog_migration_pending = true;
            self.catalog_migration_run = None;
            self.modal = Some(Modal::CatalogMigration);
            cx.notify();
        }
    }

    fn prepare_workspace_ddl_migration(&mut self, cx: &mut Context<Self>) {
        let Some(workspace_id) = self.selected_workspace_id else {
            self.show_error_toast("Select a Git-enabled workspace first".into(), cx);
            return;
        };
        let Some(sender) = &self.executor_sender else {
            return;
        };
        if sender
            .send(ExecutorCommand::PrepareWorkspaceDdlMigration { workspace_id })
            .is_ok()
        {
            self.catalog_diff = None;
            self.catalog_migration_plan = None;
            self.catalog_migration_validation = None;
            self.catalog_migration_error = None;
            self.catalog_migration_pending = true;
            self.catalog_migration_run = None;
            self.modal = Some(Modal::CatalogMigration);
            cx.notify();
        }
    }

    fn catalog_diagram_mermaid(&self) -> Option<String> {
        let diagram = self.catalog_diagram.diagram()?;
        let node_ids = diagram
            .nodes
            .iter()
            .enumerate()
            .map(|(index, node)| (node.id.clone(), format!("n{index}")))
            .collect::<HashMap<_, _>>();
        let mut output = String::from("flowchart LR\n");
        for (index, node) in diagram.nodes.iter().enumerate() {
            let label = node
                .qualified_name
                .replace('\\', "\\\\")
                .replace('"', "\\\"")
                .replace(['\r', '\n'], " ");
            output.push_str(&format!("  n{index}[\"{label}\"]\n"));
        }
        for (index, edge) in diagram.edges.iter().enumerate() {
            let Some(from) = node_ids.get(&edge.from) else {
                continue;
            };
            let to = edge
                .to
                .as_ref()
                .and_then(|id| node_ids.get(id))
                .cloned()
                .unwrap_or_else(|| format!("external{index}"));
            if edge.to.as_ref().is_none_or(|id| !node_ids.contains_key(id)) {
                let label = edge
                    .referenced_path
                    .clone()
                    .unwrap_or_else(|| "unresolved target".into())
                    .replace('"', "\\\"")
                    .replace(['\r', '\n'], " ");
                output.push_str(&format!("  {to}[\"{label}\"]\n"));
            }
            output.push_str(&format!("  {from} -->|{:?}| {to}\n", edge.kind));
        }
        Some(output)
    }

    fn copy_catalog_diagram_mermaid(&mut self, cx: &mut Context<Self>) {
        if let Some(diagram) = self.catalog_diagram_mermaid() {
            cx.write_to_clipboard(gpui::ClipboardItem::new_string(diagram));
            self.show_success_toast("Copied Mermaid catalog diagram".into(), cx);
        }
    }

    fn catalog_rollback_sql(&self) -> Option<String> {
        let plan = self.catalog_migration_plan.as_ref()?;
        let statements = plan
            .rollback_groups
            .iter()
            .flat_map(|group| &group.statements)
            .collect::<Vec<_>>();
        if statements.is_empty() {
            return None;
        }
        let mut output = format!(
            "-- Sift rollback plan for migration {}\n-- Generated only from changes marked exactly reversible. Review before executing.\n\n",
            plan.id
        );
        for statement in statements {
            output.push_str(&statement.sql);
            if !statement.sql.trim_end().ends_with(';') {
                output.push(';');
            }
            output.push_str("\n\n");
        }
        Some(output)
    }

    fn catalog_migration_sql(&self) -> Option<String> {
        let plan = self.catalog_migration_plan.as_ref()?;
        let mut output = format!(
            "-- Sift migration plan {}\n-- Digest: {}\n-- Review and validate against a test database before applying.\n\n",
            plan.id, plan.digest
        );
        for statement in plan.groups.iter().flat_map(|group| &group.statements) {
            output.push_str(&statement.sql);
            if !statement.sql.trim_end().ends_with(';') {
                output.push(';');
            }
            output.push_str("\n\n");
        }
        Some(output)
    }

    fn generate_catalog_migration_artifacts(&mut self, cx: &mut Context<Self>) {
        let Some(plan) = self.catalog_migration_plan.as_ref() else {
            return;
        };
        let Some(snapshot) = self.workspace_files.snapshot() else {
            self.show_error_toast(
                "Select a workspace before generating migration files".into(),
                cx,
            );
            return;
        };
        let Some(up) = self.catalog_migration_sql() else {
            return;
        };
        let Some(down) = self.catalog_rollback_sql() else {
            self.show_error_toast(
                "This plan has no safely generated rollback script".into(),
                cx,
            );
            return;
        };
        let stem = plan
            .digest
            .chars()
            .filter(|character| character.is_ascii_alphanumeric())
            .take(12)
            .collect::<String>();
        let stem = if stem.is_empty() {
            plan.id.to_string().chars().take(12).collect()
        } else {
            stem
        };
        let migration_path = sift_protocol::WorkspacePath(format!("{stem}.migration.sql"));
        let rollback_path = sift_protocol::WorkspacePath(format!("{stem}.rollback.sql"));
        let request = sift_api_types::WorkspaceBatchMutationRequest {
            expected_workspace_revision: snapshot.tree.workspace.revision,
            mutations: vec![
                sift_api_types::WorkspaceBatchMutationItem::Create {
                    parent_id: None,
                    path: migration_path.clone(),
                    kind: sift_protocol::WorkspaceNodeKind::SqlDocument,
                    initial_text: Some(up),
                },
                sift_api_types::WorkspaceBatchMutationItem::Create {
                    parent_id: None,
                    path: rollback_path,
                    kind: sift_protocol::WorkspaceNodeKind::SqlDocument,
                    initial_text: Some(down),
                },
            ],
        };
        let Some(sender) = &self.executor_sender else {
            return;
        };
        if sender
            .send(ExecutorCommand::GenerateMigrationArtifacts {
                workspace_id: snapshot.tree.workspace.id.0,
                request,
                migration_path,
            })
            .is_ok()
        {
            self.catalog_migration_pending = true;
            self.catalog_migration_error = None;
            cx.notify();
        }
    }

    fn copy_catalog_rollback_sql(&mut self, cx: &mut Context<Self>) {
        if let Some(sql) = self.catalog_rollback_sql() {
            cx.write_to_clipboard(gpui::ClipboardItem::new_string(sql));
            self.show_success_toast("Copied migration rollback SQL".into(), cx);
        }
    }

    fn apply_catalog_migration(&mut self, cx: &mut Context<Self>) {
        if !self.require_operation(
            sift_protocol::OperationKind::ApplyMigration,
            "Apply catalog migration",
            cx,
        ) {
            return;
        }
        let Some(plan) = self.catalog_migration_plan.as_ref() else {
            return;
        };
        let Some(sender) = &self.executor_sender else {
            return;
        };
        let request = sift_protocol::ApplyMigrationRequest {
            plan_id: plan.id,
            plan_digest: plan.digest.clone(),
            acknowledgements: plan.required_acknowledgements.clone(),
            source: self
                .catalog_migration_workspace_path
                .as_ref()
                .and_then(|path| {
                    let snapshot = self.workspace_files.snapshot()?;
                    Some(sift_protocol::VersionedExecutionContext {
                        workspace_id: snapshot.tree.workspace.id,
                        workspace_revision: snapshot.tree.workspace.revision,
                        checkpoint_id: None,
                        path: Some(path.clone()),
                        git_commit: self
                            .repository
                            .status()
                            .and_then(|status| status.head_oid.clone()),
                        source_workflow: Some("catalog_migration".into()),
                    })
                }),
        };
        if sender
            .send(ExecutorCommand::ApplyCatalogMigration { request })
            .is_ok()
        {
            self.catalog_migration_pending = true;
            cx.notify();
        }
    }

    fn validate_catalog_migration(&mut self, cx: &mut Context<Self>) {
        let Some(plan) = self.catalog_migration_plan.as_ref() else {
            return;
        };
        let Some(sender) = &self.executor_sender else {
            return;
        };
        let request = sift_protocol::ValidateMigrationRequest {
            plan_id: plan.id,
            plan_digest: plan.digest.clone(),
            confirm_test_database: true,
        };
        if sender
            .send(ExecutorCommand::ValidateCatalogMigration { request })
            .is_ok()
        {
            self.catalog_migration_pending = true;
            self.catalog_migration_validation = None;
            self.catalog_migration_error = None;
            cx.notify();
        }
    }

    fn refresh_catalog_migration_run(&mut self, cx: &mut Context<Self>) {
        let Some(run) = self.catalog_migration_run.as_ref().map(|run| run.id) else {
            return;
        };
        let Some(sender) = &self.executor_sender else {
            return;
        };
        if sender
            .send(ExecutorCommand::RefreshCatalogMigrationRun { run })
            .is_ok()
        {
            self.catalog_migration_pending = true;
            cx.notify();
        }
    }

    fn cancel_catalog_migration_run(&mut self, cx: &mut Context<Self>) {
        let Some(run) = self.catalog_migration_run.as_ref().and_then(|run| {
            (run.state == sift_protocol::MigrationRunState::Running).then_some(run.id)
        }) else {
            return;
        };
        let Some(sender) = &self.executor_sender else {
            return;
        };
        if sender
            .send(ExecutorCommand::CancelCatalogMigrationRun { run })
            .is_ok()
        {
            self.catalog_migration_pending = true;
            cx.notify();
        }
    }

    fn open_data_results_modal(
        &mut self,
        pane: &Entity<Pane>,
        item_id: u64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(results) = pane.read(cx).results.get(&item_id).cloned() else {
            return;
        };
        for candidate in &self.panes {
            candidate.update(cx, |candidate, cx| {
                if let Some(previous) = candidate.expanded_result_item {
                    if let Some(results) = candidate.results.get(&previous) {
                        results.update(cx, |results, cx| results.set_large_view(false, cx));
                    }
                }
                candidate.expanded_result_item = None;
                cx.notify();
            });
        }
        pane.update(cx, |pane, cx| {
            pane.expanded_result_item = Some(item_id);
            cx.notify();
        });
        results.update(cx, |results, cx| results.set_large_view(true, cx));
        self.focused_surface = WorkspaceSurface::Results;
        self.modal = Some(Modal::DataResults(item_id));
        results.focus_handle(cx).focus(window, cx);
        cx.notify();
    }

    fn export_active_result(
        &mut self,
        format: sift_protocol::ExportFormat,
        cx: &mut Context<Self>,
    ) {
        let Some((item_id, results, sql)) = self.panes.get(self.active_pane).and_then(|pane| {
            let pane = pane.read(cx);
            let item_id = pane.active_item()?.id;
            pane.results
                .get(&item_id)
                .cloned()
                .map(|results| (item_id, results, pane.targeted_query_sql(item_id, cx)))
        }) else {
            self.show_toast("Active tab has no result surface".into(), cx);
            return;
        };
        if results.read(cx).export_in_progress() {
            self.show_toast("Result export already in progress".into(), cx);
            return;
        }
        self.prompt_result_export(item_id, sql, format, cx);
    }

    fn prompt_result_export(
        &mut self,
        item_id: u64,
        sql: String,
        format: sift_protocol::ExportFormat,
        cx: &mut Context<Self>,
    ) {
        let params = match self.remembered_query_params(&sql) {
            Ok(params) => params,
            Err(message) => {
                self.show_error_toast(message, cx);
                return;
            }
        };
        let request = sift_protocol::ExportRequest {
            sql,
            params,
            format,
            header: true,
            null_display: None,
        };
        let title = self
            .panes
            .iter()
            .find_map(|pane| {
                pane.read(cx)
                    .items
                    .iter()
                    .find(|item| item.id == item_id)
                    .map(|item| item.title.clone())
            })
            .unwrap_or_else(|| "query-result".into());
        let suggested_name = format!("{}.{}", safe_export_stem(&title), export_extension(format));
        let prompt = cx.prompt_for_new_path(std::path::Path::new("."), Some(&suggested_name));
        cx.spawn(async move |shell, cx| {
            let result = prompt.await;
            let _ = shell.update(cx, |shell, cx| match result {
                Ok(Ok(Some(destination))) => {
                    shell.queue_result_export_to_path(item_id, destination, request, cx)
                }
                Ok(Err(error)) => {
                    shell.show_error_toast(format!("opening export folder: {error}"), cx)
                }
                Ok(Ok(None)) | Err(_) => {}
            });
        })
        .detach();
    }

    fn prompt_csv_import(&mut self, cx: &mut Context<Self>) {
        if !self.require_operation(sift_protocol::OperationKind::ImportCsv, "Import CSV", cx) {
            return;
        }
        if self.executor_sender.is_none() {
            self.show_error_toast("Connect before importing CSV data".into(), cx);
            return;
        }
        let prompt = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: false,
            multiple: false,
            prompt: Some("Import CSV as a new table".into()),
        });
        let background = cx.background_executor().clone();
        cx.spawn(async move |shell, cx| {
            let Ok(Ok(Some(paths))) = prompt.await else {
                return;
            };
            let Some(path) = paths.into_iter().next() else {
                return;
            };
            let table = csv_table_name(&path);
            let read_path = path.clone();
            let data = background
                .spawn(async move { std::fs::read(read_path) })
                .await;
            let _ = shell.update(cx, |shell, cx| match data {
                Ok(data) if data.len() <= 64 * 1024 * 1024 => match preview_csv(table, data) {
                    Ok(preview) => {
                        shell.csv_import_preview = Some(preview);
                        shell.modal = Some(Modal::CsvImport);
                        cx.notify();
                    }
                    Err(message) => shell.show_error_toast(message, cx),
                },
                Ok(_) => {
                    shell.show_error_toast("CSV import exceeds the 64 MiB payload limit".into(), cx)
                }
                Err(error) => shell
                    .show_error_toast(format!("reading CSV file {}: {error}", path.display()), cx),
            });
        })
        .detach();
    }

    fn toggle_csv_conflict_policy(&mut self, cx: &mut Context<Self>) {
        let Some(preview) = self.csv_import_preview.as_mut() else {
            return;
        };
        preview.conflict_policy = match preview.conflict_policy {
            sift_protocol::CsvConflictPolicy::Abort => sift_protocol::CsvConflictPolicy::Skip,
            sift_protocol::CsvConflictPolicy::Skip => sift_protocol::CsvConflictPolicy::Abort,
        };
        cx.notify();
    }

    fn confirm_csv_import(&mut self, cx: &mut Context<Self>) {
        let Some(preview) = self.csv_import_preview.take() else {
            return;
        };
        let Some(sender) = &self.executor_sender else {
            self.show_error_toast("Connect before importing CSV data".into(), cx);
            return;
        };
        let table = preview.table.clone();
        let request = sift_protocol::CsvImportRequest {
            table: preview.table,
            data: preview.data,
            header: true,
            delimiter: ',',
            null_value: Some("NULL".into()),
            create_table: true,
            conflict_policy: preview.conflict_policy,
        };
        if sender.send(ExecutorCommand::ImportCsv { request }).is_ok() {
            self.modal = None;
            self.show_toast(format!("Importing CSV into {table}…"), cx);
        }
    }

    #[cfg(test)]
    fn queue_result_export(
        &mut self,
        item_id: u64,
        directory: PathBuf,
        title: String,
        request: sift_protocol::ExportRequest,
        cx: &mut Context<Self>,
    ) {
        let extension = export_extension(request.format);
        let stem = safe_export_stem(&title);
        let destination = directory.join(format!("{stem}.{extension}"));
        self.queue_result_export_to_path(item_id, destination, request, cx);
    }

    fn queue_result_export_to_path(
        &mut self,
        item_id: u64,
        destination: PathBuf,
        request: sift_protocol::ExportRequest,
        cx: &mut Context<Self>,
    ) {
        let Some(sender) = &self.executor_sender else {
            self.show_error_toast("Connect before exporting results".into(), cx);
            return;
        };
        if sender
            .send(ExecutorCommand::ExportResult {
                item_id,
                destination,
                request,
            })
            .is_ok()
        {
            self.set_result_export_progress(item_id, Some(0), cx);
            self.show_toast("Exporting query result…".into(), cx);
        }
    }

    fn set_result_export_progress(
        &mut self,
        item_id: u64,
        bytes: Option<u64>,
        cx: &mut Context<Self>,
    ) {
        for pane in &self.panes {
            if let Some(results) = pane.read(cx).results.get(&item_id).cloned() {
                results.update(cx, |results, cx| results.set_export_progress(bytes, cx));
            }
        }
    }

    fn open_result_cell_editor(
        &mut self,
        pane: &Entity<Pane>,
        item_id: u64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !self.require_operation(
            sift_protocol::OperationKind::PreviewEdits,
            "Edit result data",
            cx,
        ) {
            return;
        }
        let Some(source) = pane.read(cx).database_source(item_id) else {
            self.show_error_toast("Only database table results can be edited".into(), cx);
            return;
        };
        if source.object_kind != sift_protocol::ObjectKind::Table {
            self.show_error_toast("Only base-table results can be edited".into(), cx);
            return;
        }
        let Some(results) = pane.read(cx).results.get(&item_id).cloned() else {
            return;
        };
        self.focused_surface = WorkspaceSurface::Results;
        let Some(selected) = results.read(cx).selected_cell_edit() else {
            self.show_toast("Select one result cell to edit".into(), cx);
            return;
        };
        if self
            .staged_result_item_id()
            .is_some_and(|staged| staged != item_id)
        {
            self.show_toast(
                "Apply or discard the staged table changes before editing another result".into(),
                cx,
            );
            return;
        }
        let staged_value = self
            .staged_result_edits
            .iter()
            .find(|edit| {
                edit.item_id == item_id
                    && edit.column == selected.column
                    && edit.original_row == selected.original_row
            })
            .map(|edit| edit.value.clone())
            .unwrap_or_else(|| selected.original.clone());
        let json_cell = matches!(&selected.original, sift_protocol::Value::Json(_));
        self.result_cell_edit_target = Some(ResultCellEditTarget {
            item_id,
            column: selected.column,
            original: selected.original,
            original_row: selected.original_row,
            source,
        });
        self.result_edit_pending = false;
        self.result_edit_error = None;
        if json_cell {
            let text = match &staged_value {
                sift_protocol::Value::Json(value) => {
                    serde_json::to_string_pretty(value).unwrap_or_else(|_| value.to_string())
                }
                sift_protocol::Value::Null | sift_protocol::Value::TypedNull { .. } => {
                    "NULL".into()
                }
                _ => render_value(&staged_value).text,
            };
            results.update(cx, |results, cx| {
                results.mark_selected_cell_editing(cx);
            });
            let focus = pane.update(cx, |pane, cx| {
                pane.show_database_item_view(item_id, DatabaseItemView::Json, Some(text), cx);
                pane.editor(item_id).map(|editor| editor.focus_handle(cx))
            });
            if let Some(focus) = focus {
                focus.focus(window, cx);
            }
            cx.notify();
            return;
        }
        let text = render_value(&staged_value).text;
        let focus = results.update(cx, |results, cx| results.begin_selected_cell_edit(text, cx));
        let Some(focus) = focus else {
            self.result_cell_edit_target = None;
            return;
        };
        focus.focus(window, cx);
        cx.notify();
    }

    fn submit_result_cell_edit(
        &mut self,
        pane: &Entity<Pane>,
        item_id: u64,
        text: &str,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let text = text.to_owned();
        self.result_cell_edit_input
            .update(cx, |input, cx| input.set_text(&text, cx));
        if !self.stage_current_result_edit(cx) {
            if let Some(results) = pane.read(cx).results.get(&item_id).cloned() {
                results.update(cx, |results, cx| results.set_inline_cell_edit_error(cx));
            }
            if let Some(message) = self.result_edit_error.clone() {
                self.show_error_toast(message, cx);
            }
            return;
        }
        self.sync_staged_result_cells(item_id, cx);
        if self.staged_result_change_count() == 0 {
            if let Some(results) = pane.read(cx).results.get(&item_id).cloned() {
                results.update(cx, |results, cx| results.finish_inline_cell_edit(cx));
            }
            self.result_cell_edit_target = None;
            self.focus_results(window, cx);
            cx.notify();
            return;
        }
        if let Some(results) = pane.read(cx).results.get(&item_id).cloned() {
            results.update(cx, |results, cx| results.finish_inline_cell_edit(cx));
        }
        self.result_cell_edit_target = None;
        self.focus_results(window, cx);
        self.show_toast(
            format!(
                "{} table change(s) staged",
                self.staged_result_change_count()
            ),
            cx,
        );
        cx.notify();
    }

    fn paste_result_cell_range(
        &mut self,
        pane: &Entity<Pane>,
        item_id: u64,
        text: &str,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(source) = pane.read(cx).database_source(item_id) else {
            self.show_error_toast("Only database table results can be edited".into(), cx);
            return;
        };
        if source.object_kind != sift_protocol::ObjectKind::Table {
            self.show_error_toast("Only base-table results can be edited".into(), cx);
            return;
        }
        if self
            .staged_result_item_id()
            .is_some_and(|staged| staged != item_id)
        {
            self.show_error_toast(
                "Apply or discard the staged changes for the other result first".into(),
                cx,
            );
            return;
        }
        let pasted = pane
            .read(cx)
            .results
            .get(&item_id)
            .ok_or_else(|| "Result is unavailable".to_owned())
            .and_then(|results| results.read(cx).pasted_cell_edits(text));
        let pasted = match pasted {
            Ok(pasted) => pasted,
            Err(message) => {
                self.show_error_toast(message, cx);
                return;
            }
        };
        let parsed = pasted
            .into_iter()
            .map(|edit| {
                Self::parse_result_cell_value(&edit.selected.original, &edit.text)
                    .map(|value| (edit.selected, value))
            })
            .collect::<Result<Vec<_>, _>>();
        let parsed = match parsed {
            Ok(parsed) => parsed,
            Err(message) => {
                self.show_error_toast(format!("Nothing was pasted: {message}"), cx);
                return;
            }
        };

        // Work on a copy so every conversion and coordinate succeeds before
        // any staged state changes.
        let mut staged = self.staged_result_edits.clone();
        for (selected, value) in parsed {
            if let Some(index) = staged.iter().position(|edit| {
                edit.item_id == item_id
                    && edit.column == selected.column
                    && edit.original_row == selected.original_row
            }) {
                staged.remove(index);
            }
            if value != selected.original {
                staged.push(StagedResultEdit {
                    item_id,
                    column: selected.column,
                    original: selected.original,
                    value,
                    original_row: selected.original_row,
                    source: source.clone(),
                });
            }
        }
        self.staged_result_edits = staged;
        self.pending_edit_set = None;
        self.result_edit_plan = None;
        self.result_edit_conflicts.clear();
        self.sync_staged_result_cells(item_id, cx);
        self.focus_results(window, cx);
        self.show_toast(
            format!(
                "{} table change(s) staged",
                self.staged_result_change_count()
            ),
            cx,
        );
    }

    fn cancel_result_cell_edit(
        &mut self,
        pane: &Entity<Pane>,
        item_id: u64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self
            .result_cell_edit_target
            .as_ref()
            .is_some_and(|target| target.item_id == item_id)
        {
            self.result_cell_edit_target = None;
            self.result_edit_error = None;
        }
        if let Some(results) = pane.read(cx).results.get(&item_id).cloned() {
            results.update(cx, |results, cx| results.finish_inline_cell_edit(cx));
        }
        self.focus_results(window, cx);
        cx.notify();
    }

    fn revert_selected_result_cell(
        &mut self,
        pane: &Entity<Pane>,
        item_id: u64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let selected = pane
            .read(cx)
            .results
            .get(&item_id)
            .and_then(|results| results.read(cx).selected_cell_edit());
        let Some(selected) = selected else {
            return;
        };
        let Some(index) = self.staged_result_edits.iter().position(|edit| {
            edit.item_id == item_id
                && edit.column == selected.column
                && edit.original_row == selected.original_row
        }) else {
            self.show_toast("Selected cell has no staged change".into(), cx);
            self.focus_results(window, cx);
            return;
        };
        self.revert_staged_result_edit(index, cx);
        self.focus_results(window, cx);
        self.show_toast("Reverted staged cell change".into(), cx);
    }

    fn stage_selected_result_row_delete(
        &mut self,
        pane: &Entity<Pane>,
        item_id: u64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if !self.require_operation(
            sift_protocol::OperationKind::PreviewEdits,
            "Delete table row",
            cx,
        ) {
            return;
        }
        let Some(source) = pane.read(cx).database_source(item_id) else {
            self.show_error_toast("Only database table results can be edited".into(), cx);
            return;
        };
        if source.object_kind != sift_protocol::ObjectKind::Table {
            self.show_error_toast("Only base-table rows can be deleted".into(), cx);
            return;
        }
        let Some(original_row) = pane
            .read(cx)
            .results
            .get(&item_id)
            .and_then(|results| results.read(cx).selected_cell_edit())
            .map(|selected| selected.original_row)
        else {
            self.show_toast("Select a table row to delete".into(), cx);
            return;
        };
        if self
            .staged_result_item_id()
            .is_some_and(|staged| staged != item_id)
        {
            self.show_error_toast(
                "Apply or discard the staged changes for the other result first".into(),
                cx,
            );
            return;
        }
        self.staged_result_edits
            .retain(|edit| edit.item_id != item_id || edit.original_row != original_row);
        if let Some(index) = self
            .staged_result_deletes
            .iter()
            .position(|delete| delete.item_id == item_id && delete.original_row == original_row)
        {
            self.staged_result_deletes.remove(index);
            self.show_toast("Cancelled staged row deletion".into(), cx);
        } else {
            self.staged_result_deletes.push(StagedResultDelete {
                item_id,
                original_row,
                source,
            });
            self.show_toast("Row deletion staged for review".into(), cx);
        }
        self.pending_edit_set = None;
        self.result_edit_plan = None;
        self.result_edit_conflicts.clear();
        self.sync_staged_result_cells(item_id, cx);
        self.open_staged_result_edits(item_id, window, cx);
    }

    fn staged_result_item_id(&self) -> Option<u64> {
        self.staged_result_edits
            .first()
            .map(|edit| edit.item_id)
            .or_else(|| {
                self.staged_result_deletes
                    .first()
                    .map(|delete| delete.item_id)
            })
    }

    fn staged_result_change_count(&self) -> usize {
        self.staged_result_edits.len() + self.staged_result_deletes.len()
    }

    fn parse_result_cell_value(
        original: &sift_protocol::Value,
        text: &str,
    ) -> Result<sift_protocol::Value, String> {
        use sift_protocol::Value;
        if text == "NULL"
            || (!matches!(original, Value::Json(_)) && text.eq_ignore_ascii_case("NULL"))
        {
            return Ok(Value::Null);
        }
        let invalid = || format!("{text:?} is not a valid {} value", original.type_category());
        match original {
            Value::Null | Value::TypedNull { .. } | Value::Text(_) => {
                Ok(Value::Text(text.to_owned()))
            }
            Value::Native {
                provider_id,
                type_name,
                ..
            } => Ok(Value::Native {
                provider_id: provider_id.clone(),
                type_name: type_name.clone(),
                display_text: text.to_owned(),
            }),
            Value::Bool(_) => text.parse().map(Value::Bool).map_err(|_| invalid()),
            Value::Int16(_) => text.parse().map(Value::Int16).map_err(|_| invalid()),
            Value::Int32(_) => text.parse().map(Value::Int32).map_err(|_| invalid()),
            Value::Int64(_) => text.parse().map(Value::Int64).map_err(|_| invalid()),
            Value::Float32(_) => text.parse().map(Value::Float32).map_err(|_| invalid()),
            Value::Float64(_) => text.parse().map(Value::Float64).map_err(|_| invalid()),
            Value::Decimal(_) => Ok(Value::Decimal(text.to_owned())),
            Value::Blob(_) => Err("Binary cells cannot be edited as text".into()),
            Value::Date(_) => text.parse().map(Value::Date).map_err(|_| invalid()),
            Value::Time(_) => text.parse().map(Value::Time).map_err(|_| invalid()),
            Value::Timestamp(_) => text.parse().map(Value::Timestamp).map_err(|_| invalid()),
            Value::TimestampTz(_) => text.parse().map(Value::TimestampTz).map_err(|_| invalid()),
            Value::Interval(_) => Err("Interval cells cannot be edited as text yet".into()),
            Value::Uuid(_) => text.parse().map(Value::Uuid).map_err(|_| invalid()),
            Value::Json(_) => serde_json::from_str(text)
                .map(Value::Json)
                .map_err(|error| {
                    format!(
                        "Invalid JSON at line {}, column {}: {error}",
                        error.line(),
                        error.column()
                    )
                }),
        }
    }

    fn stage_result_cell_text(&mut self, text: &str, cx: &mut Context<Self>) -> bool {
        self.result_cell_edit_input
            .update(cx, |input, cx| input.set_text(text, cx));
        self.stage_current_result_edit(cx)
    }

    fn submit_json_result_cell_edit(
        &mut self,
        item_id: u64,
        text: &str,
        preview: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self
            .result_cell_edit_target
            .as_ref()
            .is_none_or(|target| target.item_id != item_id)
        {
            return;
        }
        if !self.stage_result_cell_text(text, cx) {
            if let Some(message) = self.result_edit_error.clone() {
                self.show_error_toast(message, cx);
            }
            return;
        }
        self.sync_staged_result_cells(item_id, cx);
        if self.staged_result_change_count() == 0 {
            self.result_cell_edit_target = None;
            for pane in &self.panes {
                if let Some(results) = pane.read(cx).results.get(&item_id).cloned() {
                    results.update(cx, |results, cx| results.finish_inline_cell_edit(cx));
                }
            }
            self.show_toast("No changes to save".into(), cx);
            return;
        }
        if preview {
            self.open_staged_result_edits(item_id, window, cx);
        } else {
            self.result_cell_edit_target = None;
            self.focus_results(window, cx);
            self.apply_result_cell_edit(cx);
        }
        cx.notify();
    }

    fn stage_json_result_edit(
        &mut self,
        _: &StageJsonResultEdit,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let active = self.panes.get(self.active_pane).and_then(|pane| {
            let pane = pane.read(cx);
            let item_id = pane.active_item()?.id;
            (pane.database_item_views.get(&item_id) == Some(&DatabaseItemView::Json))
                .then(|| {
                    pane.editor(item_id)
                        .map(|editor| (item_id, editor.read(cx).document().text().to_owned()))
                })
                .flatten()
        });
        if let Some((item_id, text)) = active {
            self.submit_json_result_cell_edit(item_id, &text, false, window, cx);
        }
    }

    fn stage_current_result_edit(&mut self, cx: &mut Context<Self>) -> bool {
        let Some(target) = self.result_cell_edit_target.clone() else {
            return self.staged_result_change_count() > 0;
        };
        let text = self.result_cell_edit_input.read(cx).text().to_string();
        let value = match Self::parse_result_cell_value(&target.original, &text) {
            Ok(value) => value,
            Err(message) => {
                self.result_edit_error = Some(message);
                cx.notify();
                return false;
            }
        };
        let existing = self.staged_result_edits.iter().position(|edit| {
            edit.item_id == target.item_id
                && edit.column == target.column
                && edit.original_row == target.original_row
        });
        if let Some(index) = existing {
            self.staged_result_edits.remove(index);
        }
        if value != target.original {
            self.staged_result_edits.push(StagedResultEdit {
                item_id: target.item_id,
                column: target.column,
                original: target.original,
                value,
                original_row: target.original_row,
                source: target.source,
            });
        }
        self.pending_edit_set = None;
        self.result_edit_plan = None;
        self.result_edit_conflicts.clear();
        self.result_edit_error = None;
        cx.notify();
        true
    }

    fn sync_staged_result_cells(&mut self, item_id: u64, cx: &mut Context<Self>) {
        let edits = self
            .staged_result_edits
            .iter()
            .filter(|edit| edit.item_id == item_id)
            .cloned()
            .collect::<Vec<_>>();
        for pane in &self.panes {
            let results = pane.read(cx).results.get(&item_id).cloned();
            let Some(results) = results else { continue };
            results.update(cx, |results, cx| {
                results.clear_staged_cells(cx);
                for edit in &edits {
                    results.stage_cell_value(
                        &edit.original_row,
                        &edit.column,
                        edit.value.clone(),
                        cx,
                    );
                }
            });
        }
    }

    fn open_staged_result_edits(
        &mut self,
        item_id: u64,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.staged_result_item_id() != Some(item_id) {
            self.show_toast("No table changes are staged".into(), cx);
            return;
        }
        self.result_cell_edit_target = None;
        self.modal = Some(Modal::EditResultCell);
        self.focus_handle.focus(window, cx);
        self.preview_result_cell_edit(cx);
        cx.notify();
    }

    fn discard_staged_result_edits(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let item_ids = self
            .staged_result_edits
            .iter()
            .map(|edit| edit.item_id)
            .chain(
                self.staged_result_deletes
                    .iter()
                    .map(|delete| delete.item_id),
            )
            .collect::<HashSet<_>>();
        self.staged_result_edits.clear();
        self.staged_result_deletes.clear();
        self.result_cell_edit_target = None;
        self.result_edit_conflicts.clear();
        self.pending_edit_set = None;
        self.result_edit_plan = None;
        self.result_edit_pending = false;
        self.result_edit_error = None;
        for item_id in item_ids {
            self.sync_staged_result_cells(item_id, cx);
        }
        self.modal = None;
        self.restore_active_surface(window, cx);
        self.show_toast("Discarded staged table changes".into(), cx);
        cx.notify();
    }

    fn staged_result_edit_set(&self) -> Option<sift_protocol::EditSet> {
        let (item_id, source) = self
            .staged_result_edits
            .first()
            .map(|edit| (edit.item_id, &edit.source))
            .or_else(|| {
                self.staged_result_deletes
                    .first()
                    .map(|delete| (delete.item_id, &delete.source))
            })?;
        let mut rows: Vec<StagedResultRow> = Vec::new();
        for edit in self
            .staged_result_edits
            .iter()
            .filter(|edit| edit.item_id == item_id)
        {
            if let Some(row) = rows
                .iter_mut()
                .find(|row| row.original == edit.original_row)
            {
                row.changes.push(sift_protocol::CellEdit {
                    column: edit.column.clone(),
                    value: edit.value.clone(),
                });
            } else {
                rows.push(StagedResultRow {
                    original: edit.original_row.clone(),
                    changes: vec![sift_protocol::CellEdit {
                        column: edit.column.clone(),
                        value: edit.value.clone(),
                    }],
                });
            }
        }
        Some(sift_protocol::EditSet {
            table: sift_protocol::ObjectPath {
                catalog: source.catalog.clone(),
                schema: Some(source.schema.clone()),
                name: source.object.clone(),
                kind: Some(source.object_kind),
                routine_args: None,
            },
            edits: rows
                .into_iter()
                .map(|row| {
                    let changed_columns = row
                        .changes
                        .iter()
                        .map(|change| change.column.as_str())
                        .collect::<HashSet<_>>();
                    let original = row
                        .original
                        .into_iter()
                        .map(|(column, value)| sift_protocol::CellEdit { column, value })
                        .collect::<Vec<_>>();
                    // The key carries the complete row because the server
                    // resolves the actual identity columns. Conflict checks
                    // only need edited values; binding unrelated provider-
                    // native cells can be impossible (arrays/enums, etc.).
                    let expected = original
                        .iter()
                        .filter(|cell| changed_columns.contains(cell.column.as_str()))
                        .cloned()
                        .collect();
                    sift_protocol::RowEdit::Update {
                        key: sift_protocol::RowKey {
                            columns: original.clone(),
                        },
                        changes: row.changes,
                        expected,
                    }
                })
                .chain(
                    self.staged_result_deletes
                        .iter()
                        .filter(|delete| delete.item_id == item_id)
                        .map(|delete| {
                            let original = delete
                                .original_row
                                .iter()
                                .cloned()
                                .map(|(column, value)| sift_protocol::CellEdit { column, value })
                                .collect();
                            sift_protocol::RowEdit::Delete {
                                key: sift_protocol::RowKey { columns: original },
                                expected: Vec::new(),
                            }
                        }),
                )
                .collect(),
        })
    }

    fn preview_result_cell_edit(&mut self, cx: &mut Context<Self>) {
        if !self.stage_current_result_edit(cx) {
            return;
        }
        let Some(edit_set) = self.staged_result_edit_set() else {
            self.result_edit_error =
                Some("Stage at least one table change before previewing".into());
            cx.notify();
            return;
        };
        let Some(item_id) = self.staged_result_item_id() else {
            return;
        };
        let Some(sender) = &self.executor_sender else {
            self.result_edit_error = Some("The database executor is unavailable".into());
            cx.notify();
            return;
        };
        self.result_edit_pending = true;
        self.result_edit_error = None;
        self.result_edit_plan = None;
        self.pending_edit_set = None;
        if sender
            .send(ExecutorCommand::PreviewResultEdits { item_id, edit_set })
            .is_err()
        {
            self.result_edit_pending = false;
            self.result_edit_error = Some("The database executor stopped".into());
        }
        cx.notify();
    }

    fn apply_result_cell_edit(&mut self, cx: &mut Context<Self>) {
        if !self.require_operation(
            sift_protocol::OperationKind::ApplyEdits,
            "Apply result edits",
            cx,
        ) {
            return;
        }
        if self.result_edit_pending {
            return;
        }
        let Some(item_id) = self.staged_result_item_id() else {
            return;
        };
        let Some(edit_set) = self
            .pending_edit_set
            .clone()
            .or_else(|| self.staged_result_edit_set())
        else {
            return;
        };
        let Some(sender) = self.executor_sender.as_ref() else {
            self.result_edit_error = Some("The database executor is unavailable".into());
            cx.notify();
            return;
        };
        self.result_edit_pending = true;
        self.result_edit_error = None;
        if sender
            .send(ExecutorCommand::ApplyResultEdits { item_id, edit_set })
            .is_err()
        {
            self.result_edit_pending = false;
            self.result_edit_error = Some("The database executor stopped".into());
        }
        cx.notify();
    }

    fn revert_staged_result_edit(&mut self, index: usize, cx: &mut Context<Self>) {
        if index >= self.staged_result_edits.len() {
            return;
        }
        let item_id = self.staged_result_edits.remove(index).item_id;
        self.pending_edit_set = None;
        self.result_edit_plan = None;
        self.result_edit_conflicts.clear();
        self.result_edit_error = None;
        self.sync_staged_result_cells(item_id, cx);
        cx.notify();
    }

    fn data_results_modal_target(
        &self,
        item_id: u64,
        cx: &App,
    ) -> Option<(SharedString, Entity<ResultsView>)> {
        self.panes.iter().find_map(|pane| {
            let pane = pane.read(cx);
            let title = pane
                .items
                .iter()
                .find(|item| item.id == item_id)?
                .title
                .clone();
            let results = pane.results.get(&item_id)?.clone();
            Some((title.into(), results))
        })
    }

    fn open_server_connection(
        &mut self,
        _: &OpenServerConnection,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.open_app_bar_modal(Modal::ServerConnection, cx);
        self.server_connection_error = None;
        self.server_connection_pending = false;
        self.server_name_input.focus_handle(cx).focus(window, cx);
        cx.notify();
    }

    fn prompt_for_instance_root(&mut self, cx: &mut Context<Self>) {
        let prompt = cx.prompt_for_paths(PathPromptOptions {
            files: false,
            directories: true,
            multiple: false,
            prompt: Some("Open Existing Sift Instance".into()),
        });
        self.instance_operation_pending = true;
        self.instance_operation_error = None;
        cx.spawn(async move |shell, cx| {
            let result = prompt.await;
            let _ = shell.update(cx, |shell, cx| match result {
                Ok(Ok(Some(paths))) => {
                    if let Some(root) = paths.into_iter().next() {
                        shell.inspect_instance_root(root, cx);
                    }
                }
                Ok(Ok(None)) | Err(_) => {
                    shell.instance_operation_pending = false;
                    cx.notify();
                }
                Ok(Err(error)) => {
                    shell.instance_operation_pending = false;
                    shell.instance_operation_error =
                        Some(format!("opening folder picker: {error}"));
                    cx.notify();
                }
            });
        })
        .detach();
    }

    fn prompt_for_new_instance_root(&mut self, cx: &mut Context<Self>) {
        let prompt = cx.prompt_for_paths(PathPromptOptions {
            files: false,
            directories: true,
            multiple: false,
            prompt: Some("Choose an empty folder for the Sift instance".into()),
        });
        self.instance_operation_pending = true;
        self.instance_operation_error = None;
        cx.spawn(async move |shell, cx| {
            let result = prompt.await;
            let _ = shell.update(cx, |shell, cx| match result {
                Ok(Ok(Some(paths))) => {
                    if let Some(root) = paths.into_iter().next() {
                        shell.send_instance_command(
                            InstanceCommand::PrepareRootConfiguration { root },
                            cx,
                        );
                    }
                }
                Ok(Ok(None)) | Err(_) => {
                    shell.instance_operation_pending = false;
                    cx.notify();
                }
                Ok(Err(error)) => {
                    shell.instance_operation_pending = false;
                    shell.instance_operation_error =
                        Some(format!("opening folder picker: {error}"));
                    cx.notify();
                }
            });
        })
        .detach();
    }

    fn send_instance_command(&mut self, command: InstanceCommand, cx: &mut Context<Self>) {
        let Some(sender) = &self.instance_sender else {
            self.instance_operation_pending = false;
            self.instance_operation_error = Some("Instance manager is unavailable".into());
            cx.notify();
            return;
        };
        self.instance_operation_pending = true;
        self.instance_operation_error = None;
        if sender.send(command).is_err() {
            self.instance_operation_pending = false;
            self.instance_operation_error = Some("Instance manager stopped".into());
        }
        cx.notify();
    }

    fn open_root_configuration(&mut self, root: std::path::PathBuf, cx: &mut Context<Self>) {
        self.dismiss_app_bar_overlays(cx);
        self.send_instance_command(InstanceCommand::OpenRootConfiguration { root }, cx);
    }

    fn open_current_configuration(&mut self, cx: &mut Context<Self>) {
        self.dismiss_app_bar_overlays(cx);
        self.send_instance_command(InstanceCommand::OpenCurrentConfiguration, cx);
    }

    fn forget_instance_root(&mut self, root: std::path::PathBuf, cx: &mut Context<Self>) {
        self.send_instance_command(InstanceCommand::ForgetRoot { root }, cx);
    }

    fn save_instance_configuration(&mut self, cx: &mut Context<Self>) {
        let Some(configuration) = self.instance_configuration.clone() else {
            return;
        };
        let manifest = self
            .instance_configuration_editor
            .read(cx)
            .document()
            .text()
            .to_owned();
        self.send_instance_command(
            InstanceCommand::SaveConfiguration {
                root: configuration.root,
                manifest,
                expected_source_revision: configuration.source_revision,
                is_new: configuration.is_new,
            },
            cx,
        );
    }

    fn inspect_instance_root(&mut self, root: std::path::PathBuf, cx: &mut Context<Self>) {
        let Some(sender) = &self.instance_sender else {
            self.instance_operation_pending = false;
            self.instance_operation_error = Some("Instance manager is unavailable".into());
            cx.notify();
            return;
        };
        self.instance_operation_pending = true;
        self.instance_operation_error = None;
        if sender.send(InstanceCommand::InspectRoot { root }).is_err() {
            self.instance_operation_pending = false;
            self.instance_operation_error = Some("Instance manager stopped".into());
        }
        cx.notify();
    }

    fn connect_instance_root(&mut self, root: std::path::PathBuf, cx: &mut Context<Self>) {
        if self.server_connection_pending {
            return;
        }
        let Some(sender) = &self.instance_sender else {
            self.server_connection_error = Some("Desktop connection manager is unavailable".into());
            cx.notify();
            return;
        };
        if sender.send(InstanceCommand::StartRoot { root }).is_err() {
            self.server_connection_error = Some("Desktop connection manager stopped".into());
        } else {
            self.server_connection_pending = true;
            self.server_connection_error = None;
        }
        cx.notify();
    }

    fn apply_instance_root(&mut self, allow_destroy: bool, cx: &mut Context<Self>) {
        let (Some(sender), Some(plan)) = (&self.instance_sender, &self.instance_plan) else {
            return;
        };
        self.instance_operation_pending = true;
        self.instance_operation_error = None;
        if sender
            .send(InstanceCommand::ApplyRoot {
                root: plan.root.clone(),
                allow_destroy,
            })
            .is_err()
        {
            self.instance_operation_pending = false;
            self.instance_operation_error = Some("Instance manager stopped".into());
        }
        cx.notify();
    }

    fn import_instance_credential(&mut self, cx: &mut Context<Self>) {
        let Some(slot) = self.selected_instance_credential.clone() else {
            return;
        };
        let Some(plan) = &self.instance_plan else {
            return;
        };
        let Some(credential) = plan.credentials.iter().find(|item| item.slot == slot) else {
            return;
        };
        let secret = self.instance_secret_input.read(cx).text().to_owned();
        if secret.is_empty() {
            self.instance_operation_error = Some("Credential value is required".into());
            cx.notify();
            return;
        }
        let Some(sender) = &self.instance_sender else {
            return;
        };
        self.instance_operation_pending = true;
        self.instance_operation_error = None;
        if sender
            .send(InstanceCommand::ImportRootCredential {
                root: plan.root.clone(),
                slot,
                kind: credential.kind,
                secret,
            })
            .is_err()
        {
            self.instance_operation_pending = false;
            self.instance_operation_error = Some("Instance manager stopped".into());
        } else {
            self.instance_secret_input
                .update(cx, |input, cx| input.set_text("", cx));
        }
        cx.notify();
    }

    fn start_instance_root(&mut self, cx: &mut Context<Self>) {
        let (Some(sender), Some(plan)) = (&self.instance_sender, &self.instance_plan) else {
            return;
        };
        self.instance_operation_pending = true;
        self.instance_operation_error = None;
        if sender
            .send(InstanceCommand::StartRoot {
                root: plan.root.clone(),
            })
            .is_err()
        {
            self.instance_operation_pending = false;
            self.instance_operation_error = Some("Instance manager stopped".into());
        }
        cx.notify();
    }

    fn toggle_app_bar_modal(&mut self, modal: Modal, cx: &mut Context<Self>) {
        if self.modal.as_ref() == Some(&modal) {
            self.close_app_bar_modal(cx);
            cx.notify();
        } else {
            match &modal {
                Modal::ServerPicker => self.server_connection_error = None,
                Modal::Account => self.account_error = None,
                _ => {}
            }
            self.open_app_bar_modal(modal, cx);
        }
    }

    fn sign_in_with_password(&mut self, cx: &mut Context<Self>) {
        if self.account_pending {
            return;
        }
        let username = self
            .account_username_input
            .read(cx)
            .text()
            .trim()
            .to_owned();
        let password = self.account_password_input.read(cx).text().to_owned();
        if username.is_empty() || password.is_empty() {
            self.account_error = Some("Username and password are required".into());
            cx.notify();
            return;
        }
        let Some(sender) = &self.instance_sender else {
            self.account_error = Some("Desktop account manager is unavailable".into());
            cx.notify();
            return;
        };
        if sender
            .send(InstanceCommand::SignInWithPassword { username, password })
            .is_err()
        {
            self.account_error = Some("Desktop account manager stopped".into());
        } else {
            self.account_pending = true;
            self.account_error = None;
        }
        cx.notify();
    }

