    #[gpui::test]
    fn file_diff_refresh_preserves_the_active_hunk_identity(cx: &mut TestAppContext) {
        let window = shell(cx);
        let workspace = window.root(cx).unwrap();
        let path = sift_protocol::WorkspacePath::new("query.sql").unwrap();
        let side = sift_protocol::VcsDiffSide::IndexToWorktree;
        let hunk = |id: &str, start: u32, text: &str| sift_protocol::VcsDiffHunk {
            id: id.into(),
            old_start: start,
            old_lines: 1,
            new_start: start,
            new_lines: 1,
            header: String::new(),
            lines: vec![sift_protocol::VcsDiffLine {
                kind: sift_protocol::VcsDiffLineKind::Context,
                old_line: Some(start),
                new_line: Some(start),
                text: text.into(),
            }],
            truncated: false,
        };
        let diff = |first_text: &str| {
            Arc::new(sift_protocol::VcsDiff {
                binding_id: sift_protocol::RepositoryBindingId(9),
                side,
                base_revision: None,
                target_revision: None,
                files: vec![sift_protocol::VcsDiffFile {
                    path: path.clone(),
                    previous_path: None,
                    state: sift_protocol::VcsFileState::Modified,
                    old_digest: None,
                    new_digest: None,
                    binary: false,
                    additions: 1,
                    deletions: 1,
                    hunks: vec![
                        hunk("first", 1, first_text),
                        hunk("second", 20, "select 20;"),
                    ],
                    content_truncated: false,
                }],
                truncated: false,
            })
        };

        workspace.update(cx, |shell, cx| {
            shell.open_repository_diff_tab(&path, side, diff("select 1;"), cx);
            let pane = shell.panes[shell.active_pane].read(cx);
            let item_id = pane.active_item().unwrap().id;
            let editor = pane.editor(item_id).unwrap();
            editor.update(cx, |editor, cx| {
                assert!(editor.navigate_to_line_prefix_index("@@ ", 0, cx));
            });
            assert_eq!(shell.active_repository_hunk(cx).unwrap().1.id, "first");

            shell.open_repository_diff_tab(
                &path,
                side,
                diff("select a much longer first statement;"),
                cx,
            );
            assert_eq!(shell.active_repository_hunk(cx).unwrap().1.id, "first");
        });
    }

    #[gpui::test]
    fn visual_diff_selection_maps_only_changed_lines_to_typed_indices(cx: &mut TestAppContext) {
        let window = shell(cx);
        let workspace = window.root(cx).unwrap();
        let path = sift_protocol::WorkspacePath::new("query.sql").unwrap();
        let side = sift_protocol::VcsDiffSide::IndexToWorktree;
        workspace.update(cx, |shell, cx| {
            shell.open_repository_diff_tab(
                &path,
                side,
                Arc::new(sift_protocol::VcsDiff {
                    binding_id: sift_protocol::RepositoryBindingId(9),
                    side,
                    base_revision: None,
                    target_revision: None,
                    files: vec![sift_protocol::VcsDiffFile {
                        path: path.clone(),
                        previous_path: None,
                        state: sift_protocol::VcsFileState::Modified,
                        old_digest: None,
                        new_digest: None,
                        binary: false,
                        additions: 1,
                        deletions: 1,
                        hunks: vec![sift_protocol::VcsDiffHunk {
                            id: "a".repeat(64),
                            old_start: 1,
                            old_lines: 2,
                            new_start: 1,
                            new_lines: 2,
                            header: String::new(),
                            lines: vec![
                                sift_protocol::VcsDiffLine {
                                    kind: sift_protocol::VcsDiffLineKind::Context,
                                    old_line: Some(1),
                                    new_line: Some(1),
                                    text: "begin;".into(),
                                },
                                sift_protocol::VcsDiffLine {
                                    kind: sift_protocol::VcsDiffLineKind::Deletion,
                                    old_line: Some(2),
                                    new_line: None,
                                    text: "select 1;".into(),
                                },
                                sift_protocol::VcsDiffLine {
                                    kind: sift_protocol::VcsDiffLineKind::Addition,
                                    old_line: None,
                                    new_line: Some(2),
                                    text: "select 2;".into(),
                                },
                            ],
                            truncated: false,
                        }],
                        content_truncated: false,
                    }],
                    truncated: false,
                }),
                cx,
            );
            let pane = shell.panes[shell.active_pane].read(cx);
            let item_id = pane.active_item().unwrap().id;
            let editor = pane.editor(item_id).unwrap();
            let text = editor.read(cx).document().text().to_owned();
            let start = text.find("-select 1;").unwrap();
            let end = text.find("+select 2;").unwrap() + "+select 2;".len();
            editor.update(
                cx,
                |editor, cx| assert!(editor.select_range(start..end, cx)),
            );

            let (_, hunk_id, indices) = shell.active_repository_line_selection(cx).unwrap();
            assert_eq!(hunk_id, "a".repeat(64));
            assert_eq!(indices, vec![1, 2]);
        });
    }

    fn table_graph() -> sift_protocol::CatalogGraph {
        use sift_protocol::{
            CatalogCompleteness, CatalogCoverage, CatalogGraphData, CatalogNode,
            CatalogNodeDetails, CatalogNodeKind, CatalogObjectId, CatalogRevision, ColumnMetadata,
            DialectId, PrimitiveType, ProviderId, ProviderRef, TypeRef,
        };
        use std::collections::BTreeMap;
        let catalog_id = CatalogObjectId("catalog".into());
        let schema_id = CatalogObjectId("schema".into());
        let table_id = CatalogObjectId("table".into());
        let node = |id: CatalogObjectId,
                    kind: CatalogNodeKind,
                    name: &str,
                    qualified_name: &str,
                    parent_id: Option<CatalogObjectId>,
                    ordinal: Option<u32>,
                    details: CatalogNodeDetails| CatalogNode {
            id,
            native_id: None,
            kind,
            name: name.into(),
            qualified_name: qualified_name.into(),
            parent_id,
            ordinal,
            definition_digest: None,
            completeness: CatalogCompleteness::Complete,
            details,
            extra: BTreeMap::new(),
        };
        sift_protocol::CatalogGraph {
            revision: CatalogRevision(7),
            content_digest: "catfp:test".into(),
            invalidation_epoch: 1,
            captured_at: serde_json::from_value(serde_json::json!("2026-01-01T00:00:00Z")).unwrap(),
            provider: ProviderRef {
                provider_id: ProviderId::new("sift/postgres").unwrap(),
                dialect_id: DialectId::new("sift/postgres").unwrap(),
                provider_version: "1".into(),
            },
            database_identity: "sifttest".into(),
            data: CatalogGraphData {
                coverage: CatalogCoverage::complete(),
                nodes: vec![
                    node(
                        catalog_id.clone(),
                        CatalogNodeKind::Catalog,
                        "sifttest",
                        "sifttest",
                        None,
                        None,
                        CatalogNodeDetails::None,
                    ),
                    node(
                        schema_id.clone(),
                        CatalogNodeKind::Schema,
                        "lab",
                        "sifttest.lab",
                        Some(catalog_id),
                        None,
                        CatalogNodeDetails::None,
                    ),
                    node(
                        table_id.clone(),
                        CatalogNodeKind::Table,
                        "people",
                        "sifttest.lab.people",
                        Some(schema_id),
                        None,
                        CatalogNodeDetails::Object { routine_args: None },
                    ),
                    node(
                        CatalogObjectId("column-id".into()),
                        CatalogNodeKind::Column,
                        "id",
                        "sifttest.lab.people.id",
                        Some(table_id),
                        Some(1),
                        CatalogNodeDetails::Column {
                            column: ColumnMetadata::new(
                                "id",
                                TypeRef::Primitive(PrimitiveType::Int64),
                            ),
                        },
                    ),
                    node(
                        CatalogObjectId("column-name".into()),
                        CatalogNodeKind::Column,
                        "name",
                        "sifttest.lab.people.name",
                        Some(CatalogObjectId("table".into())),
                        Some(2),
                        CatalogNodeDetails::Column {
                            column: {
                                let mut column = ColumnMetadata::new(
                                    "name",
                                    TypeRef::Primitive(PrimitiveType::Text),
                                );
                                column.nullable = sift_protocol::Nullability::Nullable;
                                column
                            },
                        },
                    ),
                ],
                edges: Vec::new(),
            },
        }
    }

    fn table_graph_with_details() -> sift_protocol::CatalogGraph {
        use sift_protocol::{
            CatalogCompleteness, CatalogNode, CatalogNodeDetails, CatalogNodeKind, CatalogObjectId,
            ConstraintInfo, ConstraintKind, IndexInfo, IndexKind, TriggerEvent, TriggerInfo,
            TriggerTiming,
        };
        use std::collections::BTreeMap;

        let mut graph = table_graph();
        let detail_node = |id: &str,
                           kind: CatalogNodeKind,
                           name: &str,
                           details: CatalogNodeDetails| CatalogNode {
            id: CatalogObjectId(id.into()),
            native_id: None,
            kind,
            name: name.into(),
            qualified_name: format!("sifttest.lab.people.{name}"),
            parent_id: Some(CatalogObjectId("table".into())),
            ordinal: None,
            definition_digest: None,
            completeness: CatalogCompleteness::Complete,
            details,
            extra: BTreeMap::new(),
        };
        graph.data.nodes.extend([
            detail_node(
                "index-name",
                CatalogNodeKind::Index,
                "people_name_idx",
                CatalogNodeDetails::Index {
                    index: IndexInfo {
                        name: "people_name_idx".into(),
                        columns: vec!["name".into()],
                        unique: false,
                        primary_key: false,
                        kind: IndexKind::Btree,
                        partial_predicate: Some("name IS NOT NULL".into()),
                    },
                },
            ),
            detail_node(
                "relation-team",
                CatalogNodeKind::Constraint,
                "people_team_fk",
                CatalogNodeDetails::Constraint {
                    constraint: ConstraintInfo {
                        name: "people_team_fk".into(),
                        kind: ConstraintKind::ForeignKey,
                        columns: vec!["team_id".into()],
                        definition: Some("FOREIGN KEY (team_id) REFERENCES lab.teams(id)".into()),
                        references: Some("lab.teams".into()),
                    },
                },
            ),
            detail_node(
                "trigger-touch",
                CatalogNodeKind::Trigger,
                "people_touch",
                CatalogNodeDetails::Trigger {
                    trigger: TriggerInfo {
                        name: "people_touch".into(),
                        timing: TriggerTiming::Before,
                        events: vec![TriggerEvent::Update],
                        columns: vec![],
                        definition: Some(
                            "CREATE TRIGGER people_touch BEFORE UPDATE ON lab.people;".into(),
                        ),
                    },
                },
            ),
        ]);
        graph
    }

