    #[gpui::test]
    fn table_designer_previews_additive_column_mutation(cx: &mut TestAppContext) {
        let window = shell(cx);
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        let workspace = window.root(&mut cx).unwrap();
        let (sender, mut receiver) = tokio::sync::mpsc::unbounded_channel();
        workspace.update_in(&mut cx, |shell, window, cx| {
            shell.executor_sender = Some(sender);
            shell.connection_status = ConnectionStatus::Connected {
                profile_id: 2,
                name: "Demo".into(),
            };
            shell.open_table_preview(
                DatabaseObjectTarget {
                    connection: ConnectionNavEntry {
                        id: 2,
                        tenant_id: 1,
                        name: "Demo".into(),
                        provider_id: sift_protocol::ProviderId::new("sift/postgres").unwrap(),
                    },
                    catalog: "sifttest".into(),
                    schema: "lab".into(),
                    object: "people".into(),
                    object_kind: sift_protocol::ObjectKind::Table,
                },
                window,
                cx,
            );
        });
        let item_id = match receiver.try_recv().unwrap() {
            ExecutorCommand::Execute { item_id, .. } => item_id,
            _ => panic!("expected preview execution"),
        };
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::LoadTableDefinition { .. })
        ));
        workspace.update_in(&mut cx, |shell, window, cx| {
            shell.on_executor_event(
                ExecutorEvent::TableDefinitionLoaded {
                    item_id,
                    graph: Box::new(table_graph()),
                },
                cx,
            );
            shell.open_table_designer(item_id, false, window, cx);
            shell.move_table_designer_column(1, cx);
            assert_eq!(
                shell.table_designer.as_ref().unwrap().column_order,
                vec![
                    sift_protocol::CatalogObjectId("column-name".into()),
                    sift_protocol::CatalogObjectId("column-id".into()),
                ]
            );
            shell.prepare_new_table_column(cx);
            shell
                .table_column_name_input
                .update(cx, |input, cx| input.set_text("nickname", cx));
            shell
                .table_column_type_input
                .update(cx, |input, cx| input.set_text("text", cx));
            shell.show_table_designer_ddl(cx);
        });
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::PreviewTableMutation {
                item_id: preview_item,
                expected_catalog_revision: sift_protocol::CatalogRevision(7),
                mutation: sift_protocol::CatalogDiagramMutation::AddColumn { name, .. },
            }) if preview_item == item_id && name == "nickname"
        ));
        workspace.update_in(&mut cx, |shell, _, cx| {
            let pane = shell.panes[shell.active_pane].read(cx);
            let item = pane.active_item().unwrap();
            assert_eq!(item.id, item_id);
            assert_eq!(item.title, "lab.people");
            assert_eq!(
                pane.database_item_views.get(&item.id),
                Some(&DatabaseItemView::Ddl)
            );
            assert!(pane
                .items
                .iter()
                .all(|item| item.title != "lab.people DDL.sql"));
            let ddl = pane.editor(item.id).unwrap().read(cx).document().text();
            assert!(ddl.contains("CREATE TABLE \"lab\".\"people\""));
            assert!(ddl.contains("\"nickname\" text"));
            let name_position = ddl.find("\"name\" text");
            let id_position = ddl.find("\"id\" bigint");
            assert!(
                name_position
                    .zip(id_position)
                    .is_some_and(|(name, id)| name < id),
                "{ddl}"
            );
        });
    }

