    #[gpui::test]
    fn numeric_palette_command_jumps_in_editor_and_data_contexts(cx: &mut TestAppContext) {
        let window = shell(cx);
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        let workspace = window.root(&mut cx).unwrap();
        let (editor, results) = workspace.read_with(&cx, |shell, cx| {
            let pane = shell.panes[shell.active_pane].read(cx);
            let item = pane.active_item().unwrap();
            (
                pane.editor(item.id).unwrap(),
                pane.results.get(&item.id).unwrap().clone(),
            )
        });

        workspace.update_in(&mut cx, |shell, window, cx| {
            editor.update(cx, |editor, cx| {
                editor.replace_text_from_owner("one\ntwo\nthree", cx)
            });
            shell.focused_surface = WorkspaceSurface::Editor;
            shell.open_command_palette_with_query("3", window, cx);
            assert!(matches!(
                shell.command_palette_items(cx).as_slice(),
                [CommandPaletteMatch {
                    item: CommandPaletteItem::Line(3),
                    ..
                }]
            ));
            shell.palette_confirm(&PaletteConfirm, window, cx);
        });
        assert_eq!(editor.read_with(&cx, |editor, _| editor.cursor_offset()), 8);

        results.update(&mut cx, |results, cx| {
            results.set_state(
                ResultState::Ready(crate::results::ResultData {
                    columns: vec![crate::results::ResultColumn {
                        name: "id".into(),
                        type_label: "int64".into(),
                        nullable: false,
                    }],
                    rows: (1..=3)
                        .map(|value| {
                            sift_protocol::Row::new(vec![sift_protocol::Value::Int64(value)])
                        })
                        .collect(),
                    ..Default::default()
                }),
                cx,
            );
        });
        workspace.update_in(&mut cx, |shell, window, cx| {
            shell.focus_results(window, cx);
            shell.open_command_palette_with_query("2", window, cx);
            shell.palette_confirm(&PaletteConfirm, window, cx);
        });
        assert_eq!(
            results.read_with(&cx, |results, _| results.selected_cell()),
            Some((1, 0))
        );
        assert!(workspace.read_with(&cx, |shell, _| shell.focused_surface
            == WorkspaceSurface::Results));
    }

    #[gpui::test]
    fn vim_colon_opens_contextual_write_from_data_grid(cx: &mut TestAppContext) {
        let window = shell(cx);
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        let workspace = window.root(&mut cx).unwrap();
        let (sender, mut receiver) = tokio::sync::mpsc::unbounded_channel();

        workspace.update_in(&mut cx, |workspace, window, cx| {
            let item_id = workspace.panes[workspace.active_pane]
                .read(cx)
                .active_item()
                .unwrap()
                .id;
            workspace.executor_sender = Some(sender);
            workspace.staged_result_edits = vec![StagedResultEdit {
                item_id,
                column: "action".into(),
                original: sift_protocol::Value::Text("open".into()),
                value: sift_protocol::Value::Text("closed".into()),
                original_row: vec![
                    ("id".into(), sift_protocol::Value::Int64(1)),
                    ("action".into(), sift_protocol::Value::Text("open".into())),
                ],
                source: DatabaseObjectSource {
                    instance_id: "local".into(),
                    tenant_id: 1,
                    profile_id: 2,
                    profile_name: "demo/postgres".into(),
                    provider_id: sift_protocol::Engine::Postgres.provider_id(),
                    catalog: Some("sifttest".into()),
                    schema: "audit".into(),
                    object: "events".into(),
                    object_kind: sift_protocol::ObjectKind::Table,
                    last_refreshed_at_ms: None,
                },
            }];
            let results = workspace.focused_pane_results(cx).unwrap();
            results.focus_handle(cx).focus(window, cx);
            workspace.focused_surface = WorkspaceSurface::Editor;
        });
        cx.simulate_keystrokes(": w");

        workspace.read_with(&cx, |workspace, cx| {
            assert_eq!(workspace.focused_surface, WorkspaceSurface::Results);
            assert_eq!(workspace.modal(), Some(&Modal::CommandPalette));
            assert_eq!(
                workspace
                    .filtered_commands(cx)
                    .iter()
                    .map(|command| command.id)
                    .collect::<Vec<_>>(),
                vec![CommandId::SaveItem]
            );
        });
        cx.simulate_keystrokes("enter");
        assert!(matches!(
            receiver.try_recv(),
            Ok(ExecutorCommand::ApplyResultEdits { .. })
        ));
        assert!(workspace.read_with(&cx, |workspace, _| {
            workspace.focused_surface == WorkspaceSurface::Results && workspace.result_edit_pending
        }));
        assert!(cx.update(|window, cx| { workspace.read(cx).active_results_focused(window, cx) }));
    }

