    #[gpui::test]
    fn single_tab_edge_drag_replaces_its_source_pane(cx: &mut TestAppContext) {
        let window = shell(cx);
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        let workspace = window.root(&mut cx).unwrap();
        cx.run_until_parked();

        let tab = cx.debug_bounds("tab-1").expect("only tab");
        let pane = cx.debug_bounds("pane-body-1").expect("only pane body");
        let start = tab.center();
        cx.simulate_mouse_down(start, MouseButton::Left, Modifiers::default());
        cx.simulate_mouse_move(
            point(start.x + px(6.), start.y + px(20.)),
            MouseButton::Left,
            Modifiers::default(),
        );
        let drop = point(pane.left() + px(10.), pane.center().y);
        cx.simulate_mouse_move(drop, MouseButton::Left, Modifiers::default());
        cx.run_until_parked();

        let preview = cx
            .debug_bounds("pane-drop-preview-before")
            .expect("Zed-style local split preview");
        assert_eq!(preview.left(), pane.left());
        assert_eq!(preview.top(), pane.top());
        assert_eq!(preview.size.width, pane.size.width / 2.0);
        assert_eq!(preview.size.height, pane.size.height);

        cx.simulate_mouse_up(drop, MouseButton::Left, Modifiers::default());
        cx.run_until_parked();
        workspace.read_with(&cx, |shell, cx| {
            assert_eq!(shell.panes.len(), 1);
            assert!(shell.panes[0].read(cx).contains_item(1));
            assert_eq!(
                pane_layout::pane_ids(&shell.pane_layout),
                vec![shell.panes[0].read(cx).id]
            );
        });
    }

    #[gpui::test]
    fn sole_tab_vertical_move_previews_the_post_collapse_region(cx: &mut TestAppContext) {
        let mut state = PresentationState::default();
        state.workspace.panes[0].items.push(ItemPresentation {
            id: 2,
            kind: ItemKind::Query,
            title: "two.sql".into(),
            dirty: false,
            source: None,
            last_result: None,
        });
        let window = shell_with_state(state, cx);
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        let workspace = window.root(&mut cx).unwrap();
        workspace.update_in(&mut cx, |shell, window, cx| {
            let source = shell.panes[0].clone();
            shell.move_item_to_target(source.clone(), 1, PaneDropTarget::Below, window, cx);
        });
        cx.run_until_parked();

        let source = cx.debug_bounds("tab-2").expect("upper sole tab");
        let target_id = workspace.read_with(&cx, |shell, cx| {
            shell
                .panes
                .iter()
                .find(|pane| pane.read(cx).contains_item(1))
                .expect("lower pane")
                .read(cx)
                .id
        });
        assert_eq!(target_id, 3);
        let target = cx.debug_bounds("pane-body-3").expect("lower pane body");
        let target_slot = cx.debug_bounds("pane-slot-1").expect("lower pane slot");
        let start = source.center();
        cx.simulate_mouse_down(start, MouseButton::Left, Modifiers::default());
        cx.simulate_mouse_move(
            point(start.x + px(6.), start.y + px(20.)),
            MouseButton::Left,
            Modifiers::default(),
        );
        let drop = point(target.center().x, target.bottom() - px(10.));
        cx.simulate_mouse_move(drop, MouseButton::Left, Modifiers::default());
        cx.run_until_parked();

        let preview = cx
            .debug_bounds("root-pane-drop-preview-below")
            .expect("post-collapse drop preview");
        assert_eq!(preview.left(), target_slot.left());
        assert_eq!(preview.right(), target_slot.right());
        assert_eq!(preview.bottom(), target_slot.bottom());
        assert!(preview.top() <= target_slot.top());
        assert!(preview.size.height >= target_slot.size.height);

        cx.simulate_mouse_up(drop, MouseButton::Left, Modifiers::default());
        cx.run_until_parked();
        workspace.read_with(&cx, |shell, cx| {
            let PaneLayoutPresentation::Split { axis, flexes, .. } = &shell.pane_layout else {
                panic!("vertical split remains")
            };
            assert_eq!(*axis, PaneAxis::Vertical);
            assert_eq!(flexes, &vec![1.0, 1.0]);
            assert!(
                shell
                    .panes
                    .iter()
                    .all(|pane| !pane.read(cx).suppress_tab_drag_preview),
                "drop cleanup must restore leaf previews"
            );
        });
    }

    #[gpui::test]
    fn sole_tab_can_turn_a_horizontal_pair_into_a_vertical_split(cx: &mut TestAppContext) {
        let mut state = PresentationState::default();
        state.workspace.panes[0].items.push(ItemPresentation {
            id: 2,
            kind: ItemKind::Query,
            title: "two.sql".into(),
            dirty: false,
            source: None,
            last_result: None,
        });
        let window = shell_with_state(state, cx);
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        let workspace = window.root(&mut cx).unwrap();
        workspace.update_in(&mut cx, |shell, window, cx| {
            let source = shell.panes[0].clone();
            shell.move_item_to_target(source.clone(), 1, PaneDropTarget::After, window, cx);
        });
        cx.run_until_parked();

        let left_slot = cx.debug_bounds("pane-slot-0").expect("left pane");
        let right_slot = cx.debug_bounds("pane-slot-1").expect("right pane");
        let source = cx.debug_bounds("tab-2").expect("left sole tab");
        let target = cx.debug_bounds("pane-body-3").expect("right pane body");
        let start = source.center();
        cx.simulate_mouse_down(start, MouseButton::Left, Modifiers::default());
        cx.simulate_mouse_move(
            point(start.x + px(6.), start.y + px(20.)),
            MouseButton::Left,
            Modifiers::default(),
        );
        let drop = point(target.center().x, target.top() + px(10.));
        cx.simulate_mouse_move(drop, MouseButton::Left, Modifiers::default());
        cx.run_until_parked();

        let preview = cx
            .debug_bounds("root-pane-drop-preview-above")
            .expect("vertical split preview");
        workspace.read_with(&cx, |shell, cx| {
            let target = shell
                .panes
                .iter()
                .find(|pane| pane.read(cx).id == 3)
                .expect("right target pane")
                .read(cx);
            assert_eq!(shell.root_tab_drop_target, Some(PaneDropTarget::Above));
            assert!(target.suppress_tab_drag_preview);
        });
        assert!(
            cx.debug_bounds("pane-drop-preview-above").is_none(),
            "the root target must suppress the overlapping leaf preview"
        );
        assert_eq!(preview.left(), left_slot.left());
        assert_eq!(preview.right(), right_slot.right());
        assert_eq!(preview.top(), left_slot.top());
        assert!(preview.size.height >= left_slot.size.height / 2.0);

        cx.simulate_mouse_up(drop, MouseButton::Left, Modifiers::default());
        cx.run_until_parked();
        workspace.read_with(&cx, |shell, _| {
            let PaneLayoutPresentation::Split { axis, flexes, .. } = &shell.pane_layout else {
                panic!("two-pane split remains")
            };
            assert_eq!(*axis, PaneAxis::Vertical);
            assert_eq!(flexes, &vec![1.0, 1.0]);
        });
    }

