    #[gpui::test]
    fn inline_result_edits_stage_then_review_sql_before_apply(cx: &mut TestAppContext) {
        let window = shell(cx);
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        let workspace = window.root(&mut cx).unwrap();
        let (sender, mut receiver) = tokio::sync::mpsc::unbounded_channel();

        let (item_id, results) = workspace.update_in(&mut cx, |shell, window, cx| {
            shell.open_table_preview(
                DatabaseObjectTarget {
                    connection: ConnectionNavEntry {
                        id: 2,
                        tenant_id: 1,
                        name: "demo/postgres".into(),
                        provider_id: sift_protocol::Engine::Postgres.provider_id(),
                    },
                    catalog: "sifttest".into(),
                    schema: "audit".into(),
                    object: "events".into(),
                    object_kind: sift_protocol::ObjectKind::Table,
                },
                window,
                cx,
            );
            let pane = shell.panes[shell.active_pane].clone();
            let item_id = pane.read(cx).active_item().unwrap().id;
            let results = pane.read(cx).results.get(&item_id).unwrap().clone();
            results.update(cx, |results, cx| {
                results.set_state(
                    ResultState::Ready(crate::results::ResultData {
                        columns: vec![crate::results::ResultColumn {
                            name: "action".into(),
                            type_label: "text".into(),
                            nullable: false,
                        }],
                        rows: vec![sift_protocol::Row::new(vec![sift_protocol::Value::Text(
                            "open".into(),
                        )])],
                        ..Default::default()
                    }),
                    cx,
                );
                results.select_cell(0, 0, cx);
            });
            shell.executor_sender = Some(sender);
            (item_id, results)
        });
        cx.run_until_parked();
        let row = cx.debug_bounds("result-row-0").expect("result row");
        let cell = point(
            row.left() + px(crate::results::ROW_NUMBER_WIDTH + 12.0),
            row.top() + px(crate::results::ROW_HEIGHT / 2.0),
        );
        cx.simulate_event(gpui::MouseDownEvent {
            position: cell,
            modifiers: Modifiers::default(),
            button: MouseButton::Left,
            click_count: 2,
            first_mouse: false,
        });
        cx.simulate_mouse_up(cell, MouseButton::Left, Modifiers::default());
        cx.run_until_parked();
        assert_eq!(
            results.read_with(&cx, |results, cx| results.inline_cell_edit_status(cx)),
            Some(("open".into(), false)),
            "double-click should mount and focus the inline editor"
        );
        assert!(cx.update(|window, cx| {
            results
                .read(cx)
                .inline_cell_edit_focus(cx)
                .is_some_and(|focus| focus.is_focused(window))
        }));
        cx.update(|window, cx| results.focus_handle(cx).focus(window, cx));
        cx.simulate_click(cell, Modifiers::default());
        cx.run_until_parked();
        assert!(cx.update(|window, cx| {
            results
                .read(cx)
                .inline_cell_edit_focus(cx)
                .is_some_and(|focus| focus.is_focused(window))
        }));
        results.update(&mut cx, |results, cx| {
            results.set_inline_cell_edit_text("closed", cx)
        });
        cx.run_until_parked();
        while receiver.try_recv().is_ok() {}
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();

        workspace.read_with(&cx, |shell, cx| {
            assert!(!shell.result_edit_pending);
            assert!(!matches!(shell.modal, Some(Modal::EditResultCell)));
            assert_eq!(shell.staged_result_edits.len(), 1);
            assert_eq!(results.read(cx).staged_cell_count(), 1);
            assert_eq!(results.read(cx).inline_cell_edit_status(cx), None);
        });
        assert!(
            receiver.try_recv().is_err(),
            "Enter should only stage the edit"
        );
        assert!(cx.update(|window, cx| workspace.read(cx).active_results_focused(window, cx)));
        assert!(!cx.update(|window, cx| workspace.read(cx).active_editor_focused(window, cx)));
        let pane = workspace.read_with(&cx, |shell, _| shell.panes[shell.active_pane].clone());
        workspace.update_in(&mut cx, |shell, window, cx| {
            shell.open_result_cell_editor(&pane, item_id, window, cx)
        });
        results.update(&mut cx, |results, cx| {
            results.set_inline_cell_edit_text("open", cx)
        });
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        workspace.read_with(&cx, |shell, cx| {
            assert!(shell.staged_result_edits.is_empty());
            assert_eq!(results.read(cx).staged_cell_count(), 0);
        });

        workspace.update_in(&mut cx, |shell, window, cx| {
            shell.open_result_cell_editor(&pane, item_id, window, cx)
        });
        results.update(&mut cx, |results, cx| {
            results.set_inline_cell_edit_text("closed", cx)
        });
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        workspace.read_with(&cx, |shell, cx| {
            assert_eq!(shell.staged_result_edits.len(), 1);
            assert_eq!(results.read(cx).staged_cell_count(), 1);
        });
        let review = cx
            .debug_bounds("review-staged-result-edits")
            .expect("staged edit review button");
        cx.simulate_click(review.center(), Modifiers::default());
        cx.run_until_parked();

        let ExecutorCommand::PreviewResultEdits { edit_set, .. } = receiver.try_recv().unwrap()
        else {
            panic!("review should request generated SQL")
        };
        let sift_protocol::RowEdit::Update { changes, .. } = &edit_set.edits[0] else {
            panic!("inline cell edit should be an update")
        };
        assert_eq!(
            changes[0].value,
            sift_protocol::Value::Text("closed".into())
        );
        workspace.update(&mut cx, |shell, cx| {
            shell.on_executor_event(
                ExecutorEvent::ResultEditsPreviewed {
                    item_id,
                    edit_set: edit_set.clone(),
                    result: Ok(sift_protocol::EditPlan {
                        table: edit_set.table.clone(),
                        identity: sift_protocol::IdentitySource::PrimaryKey {
                            columns: vec!["action".into()],
                        },
                        statements: vec![sift_protocol::EditStatement {
                            edit_index: 0,
                            kind: sift_protocol::EditStatementKind::Update,
                            sql: "UPDATE audit.events SET action = $1 WHERE action = $2".into(),
                            params: vec![
                                sift_protocol::Value::Text("closed".into()),
                                sift_protocol::Value::Text("open".into()),
                            ],
                        }],
                    }),
                },
                cx,
            );
        });
        cx.run_until_parked();
        assert!(cx.debug_bounds("result-edit-statement-0").is_some());
        let apply = cx
            .debug_bounds("apply-result-cell-edit")
            .expect("apply staged changes button");
        cx.simulate_click(apply.center(), Modifiers::default());
        cx.run_until_parked();
        let ExecutorCommand::ApplyResultEdits { edit_set, .. } = receiver.try_recv().unwrap()
        else {
            panic!("confirmed staged changes should apply")
        };
        assert_eq!(edit_set.edits.len(), 1);
        workspace.update(&mut cx, |shell, cx| {
            shell.on_executor_event(
                ExecutorEvent::ResultEditsApplied {
                    item_id,
                    result: Ok(sift_protocol::ApplyEditsResult {
                        applied: vec![sift_protocol::EditOutcome {
                            edit_index: 0,
                            kind: sift_protocol::EditStatementKind::Update,
                            affected_rows: 1,
                            returned: Vec::new(),
                        }],
                        committed: true,
                    }),
                },
                cx,
            );
        });
        cx.run_until_parked();
        assert!(cx.update(|window, cx| results.focus_handle(cx).is_focused(window)));
        assert_eq!(
            results.read_with(&cx, |results, _| {
                results.selected_cell_edit().map(|edit| edit.original)
            }),
            Some(sift_protocol::Value::Text("closed".into())),
            "a successful Enter save must replace the cached value immediately"
        );
        assert!(
            receiver.try_recv().is_err(),
            "saving a cell must not re-run an unordered table preview and move the row"
        );
    }

    #[gpui::test]
    fn json_result_edit_uses_table_view_and_skips_unedited_native_conflicts(
        cx: &mut TestAppContext,
    ) {
        let window = shell(cx);
        let mut cx = VisualTestContext::from_window(window.into(), cx);
        let workspace = window.root(&mut cx).unwrap();
        let (sender, mut receiver) = tokio::sync::mpsc::unbounded_channel();

        workspace.update_in(&mut cx, |shell, window, cx| {
            shell.open_table_preview(
                DatabaseObjectTarget {
                    connection: ConnectionNavEntry {
                        id: 2,
                        tenant_id: 1,
                        name: "demo/postgres".into(),
                        provider_id: sift_protocol::Engine::Postgres.provider_id(),
                    },
                    catalog: "sifttest".into(),
                    schema: "audit".into(),
                    object: "events".into(),
                    object_kind: sift_protocol::ObjectKind::Table,
                },
                window,
                cx,
            );
            let pane = shell.panes[shell.active_pane].clone();
            let item_id = pane.read(cx).active_item().unwrap().id;
            let results = pane.read(cx).results.get(&item_id).unwrap().clone();
            results.update(cx, |results, cx| {
                results.set_state(
                    ResultState::Ready(crate::results::ResultData {
                        columns: vec![
                            crate::results::ResultColumn {
                                name: "id".into(),
                                type_label: "int64".into(),
                                nullable: false,
                            },
                            crate::results::ResultColumn {
                                name: "payload".into(),
                                type_label: "jsonb".into(),
                                nullable: false,
                            },
                            crate::results::ResultColumn {
                                name: "tags".into(),
                                type_label: "text[]".into(),
                                nullable: true,
                            },
                        ],
                        rows: vec![sift_protocol::Row::new(vec![
                            sift_protocol::Value::Int64(1),
                            sift_protocol::Value::Json(serde_json::json!({"event": "open"})),
                            sift_protocol::Value::Native {
                                provider_id: sift_protocol::Engine::Postgres.provider_id(),
                                type_name: "text[]".into(),
                                display_text: "{demo}".into(),
                            },
                        ])],
                        ..Default::default()
                    }),
                    cx,
                );
                results.select_cell(0, 1, cx);
            });
            shell.show_result_row_json(item_id, window, cx);
            assert_eq!(
                shell.result_inspector_views.get(&item_id),
                Some(&ResultInspectorView::RowJson)
            );
            assert_eq!(
                results.read(cx).selected_row_json().unwrap().value,
                serde_json::json!({
                    "id": 1,
                    "payload": {"event": "open"},
                    "tags": "{demo}"
                })
            );
            shell.open_result_cell_editor(&pane, item_id, window, cx);
            assert_eq!(
                pane.read(cx).database_item_views.get(&item_id),
                Some(&DatabaseItemView::Json)
            );
            assert_eq!(
                pane.read(cx)
                    .editor(item_id)
                    .unwrap()
                    .read(cx)
                    .document()
                    .text(),
                "{\n  \"event\": \"open\"\n}"
            );
            assert!(!pane.read(cx).database_json_dirty(item_id, cx));
            assert_eq!(
                pane.read(cx).execution_sql(item_id, "{\"event\":\"open\"}"),
                table_preview_sql(
                    &sift_protocol::Engine::Postgres.provider_id(),
                    "audit",
                    "events"
                ),
                "execute-statement must use the retained query behind the JSON viewer"
            );

            shell.executor_sender = Some(sender);
            pane.read(cx)
                .editor(item_id)
                .unwrap()
                .update(cx, |editor, cx| {
                    editor.replace_text_from_owner("{\n  \"event\": \"close\"\n}", cx)
                });
            assert!(pane.read(cx).database_json_dirty(item_id, cx));
            shell.save_active_item(&SaveActiveItem, window, cx);
        });

        cx.run_until_parked();
        assert!(cx.debug_bounds("preview-json-result-edit").is_some());
        assert!(cx.debug_bounds("save-json-result-edit").is_some());

        let ExecutorCommand::ApplyResultEdits { edit_set, .. } = receiver.try_recv().unwrap()
        else {
            panic!("JSON :w should apply without previewing")
        };
        workspace.read_with(&cx, |shell, _| {
            assert_eq!(shell.staged_result_edits.len(), 1);
            let sift_protocol::RowEdit::Update { expected, .. } = &edit_set.edits[0] else {
                panic!("JSON cell edit should be an update")
            };
            assert_eq!(expected.len(), 1);
            assert_eq!(expected[0].column, "payload");
        });
    }

